1	/**
2	 * @byte5ai/palaia — palaia Memory Backend for OpenClaw
3	 *
4	 * Plugin entry point. Loaded by OpenClaw via jiti (no build step needed).
5	 *
6	 * Registers:
7	 * - Tools: memory_search, memory_get, memory_write
8	 * - MemoryPromptSection: Guided tool usage hints
9	 * - Session hooks (always): session_start, session_end, before_reset,
10	 *   llm_input, llm_output, after_tool_call, subagent_spawning, subagent_ended
11	 * - ContextEngine (modern) OR legacy hooks (before_prompt_build, agent_end,
12	 *   message_received, message_sending)
13	 *
14	 * v3.0 Features:
15	 * - Session continuity: Auto-briefing on session start / LLM switch
16	 * - Session summaries: Auto-saved on session end / reset
17	 * - Tool observations: Tracked via after_tool_call
18	 * - Progressive disclosure: Compact mode for large memory stores
19	 * - Privacy markers: <private> blocks excluded from capture
20	 * - Recency boost: Fresh memories ranked higher
21	 *
22	 * Activation:
23	 *   plugins: { slots: { memory: "palaia" } }
24	 */
25	
26	import { resolveConfig, type PalaiaPluginConfig } from "./src/config.js";
27	import { registerTools } from "./src/tools.js";
28	import { registerHooks } from "./src/hooks/index.js";
29	import { registerSessionHooks } from "./src/hooks/session.js";
30	import { createPalaiaContextEngine } from "./src/context-engine.js";
31	import type { OpenClawPluginApi, OpenClawPluginEntry } from "./src/types.js";
32	
33	// Plugin entry point compatible with OpenClaw plugin-sdk definePluginEntry
34	const palaiaPlugin: OpenClawPluginEntry = {
35	  id: "palaia",
36	  name: "palaia Memory",
37	  register(api: OpenClawPluginApi) {
38	    // Issue #66: Plugin config is resolved GLOBALLY via api.pluginConfig.
39	    // OpenClaw does NOT provide per-agent config resolution — all agents share the same
40	    // plugin config from openclaw.json → plugins.entries.palaia.config.
41	    // See: https://github.com/byte5ai/palaia/issues/66
42	    const rawConfig = api.pluginConfig as
43	      | Partial<PalaiaPluginConfig>
44	      | undefined;
45	    const config = resolveConfig(rawConfig);
46	
47	    // If workspace not set, use agent workspace from context
48	    if (!config.workspace && api.workspace) {
49	      config.workspace = typeof api.workspace === "string"
50	        ? api.workspace
51	        : api.workspace.dir;
52	    }
53	
54	    // Register agent tools (memory_search, memory_get, memory_write)
55	    registerTools(api, config);
56	
57	    // Register MemoryPromptSection for guided memory tool usage (v3.0)
58	    if (api.registerMemoryPromptSection) {
59	      api.registerMemoryPromptSection(({ availableTools }) => {
60	        const lines: string[] = [];
61	        if (availableTools.has("memory_search")) {
62	          lines.push("Use `memory_search` to find relevant memories by semantic query.");
63	        }
64	        if (availableTools.has("memory_get")) {
65	          lines.push("Use `memory_get <id>` to retrieve full memory details by ID.");
66	        }
67	        if (availableTools.has("memory_write")) {
68	          lines.push("Use `memory_write` for processes/SOPs and tasks only — conversation knowledge is auto-captured.");
69	        }
70	        return lines;
71	      });
72	    }
73	
74	    // Session lifecycle hooks are always registered (session_start, session_end,
75	    // before_reset, llm_input, llm_output, after_tool_call).
76	    // These work independently of the ContextEngine vs legacy hooks choice.
77	    registerSessionHooks(api, config);
78	
79	    // Register ContextEngine when available, otherwise use legacy hooks
80	    if (api.registerContextEngine) {
81	      api.registerContextEngine("palaia", () => createPalaiaContextEngine(api, config));
82	    } else {
83	      registerHooks(api, config);  // Legacy fallback
84	    }
85	  },
86	};
87	
88	export default palaiaPlugin;
