55	/**
56	 * Resolve the effective capture scope from priorities (per-agent override)
57	 * falling back to plugin config, then to "team".
58	 */
59	async function getEffectiveCaptureScope(config: PalaiaPluginConfig): Promise<string> {
60	  try {
61	    const prio = await loadPriorities(config.workspace || "");
62	    const agentId = process.env.PALAIA_AGENT || undefined;
63	    const resolved = resolvePriorities(prio, {
64	      recallTypeWeight: config.recallTypeWeight,
65	      recallMinScore: config.recallMinScore,
66	      maxInjectedChars: config.maxInjectedChars,
67	      tier: config.tier,
68	    }, agentId);
69	    if (resolved.captureScope) return resolved.captureScope;
70	  } catch {
71	    // Fall through to config default
72	  }
73	  return config.captureScope || "team";
74	}
