76	function buildRunnerOpts(config: PalaiaPluginConfig, overrides?: { workspace?: string }): RunnerOpts {
77	  return {
78	    binaryPath: config.binaryPath,
79	    workspace: overrides?.workspace || config.workspace,
80	    timeoutMs: config.timeoutMs,
81	  };
82	}
83	
84	/** Rough token estimate: ~4 chars per token for English text. */
85	function estimateTokens(text: string): number {
86	  return Math.ceil(text.length / 4);
87	}
