89	/**
90	 * Build the memory context string from recall results.
91	 * Used by the ContextEngine assemble() method.
92	 */
93	async function buildMemoryContext(
94	  config: PalaiaPluginConfig,
95	  opts: RunnerOpts,
96	  messages: unknown[],
97	  maxChars: number,
98	): Promise<{ text: string; recallOccurred: boolean; recallMinScore: number }> {
99	  // Load and resolve priorities (Issue #121)
100	  const prio = await loadPriorities(config.workspace || "");
101	  const agentId = process.env.PALAIA_AGENT || undefined;
102	  const project = config.captureProject || undefined;
103	  const resolvedPrio = resolvePriorities(prio, {
104	    recallTypeWeight: config.recallTypeWeight,
105	    recallMinScore: config.recallMinScore,
106	    maxInjectedChars: config.maxInjectedChars,
107	    tier: config.tier,
108	  }, agentId, project);
109	
110	  const effectiveMaxChars = Math.min(resolvedPrio.maxInjectedChars || 4000, maxChars);
111	  const limit = Math.min(config.maxResults || 10, 20);
112	  let entries: QueryResult["results"] = [];
113	
114	  if (config.recallMode === "query" && messages.length > 0) {
115	    const userMessage = buildRecallQuery(messages);
116	    if (userMessage && userMessage.length >= 5) {
117	      // Try embed server first
118	      let serverQueried = false;
119	      if (config.embeddingServer) {
120	        try {
121	          const mgr = getEmbedServerManager(opts);
122	          const resp = await mgr.query({
123	            text: userMessage,
124	            top_k: limit,
125	            include_cold: resolvedPrio.tier === "all",
126	            ...(resolvedPrio.scopeVisibility ? { scope_visibility: resolvedPrio.scopeVisibility } : {}),
127	          }, config.timeoutMs || 3000);
128	          if (resp?.result?.results && Array.isArray(resp.result.results)) {
129	            entries = resp.result.results;
130	            serverQueried = true;
131	          }
132	        } catch {
133	          // Fall through to CLI
134	        }
135	      }
136	
137	      if (!serverQueried) {
138	        try {
139	          const { runJson } = await import("./runner.js");
140	          const queryArgs: string[] = ["query", userMessage, "--limit", String(limit)];
141	          if (resolvedPrio.tier === "all") queryArgs.push("--all");
142	          const result = await runJson<QueryResult>(queryArgs, { ...opts, timeoutMs: 15000 });
143	          if (result && Array.isArray(result.results)) {
144	            entries = result.results;
145	          }
146	        } catch {
147	          // Fall through to list
148	        }
149	      }
150	    }
151	  }
152	
153	  // List fallback
154	  if (entries.length === 0) {
155	    try {
156	      const { runJson } = await import("./runner.js");
157	      const listArgs: string[] = ["list"];
158	      if (resolvedPrio.tier === "all") {
159	        listArgs.push("--all");
160	      } else {
161	        listArgs.push("--tier", resolvedPrio.tier || "hot");
162	      }
163	      const result = await runJson<QueryResult>(listArgs, opts);
164	      if (result && Array.isArray(result.results)) {
165	        entries = result.results;
166	      }
167	    } catch {
168	      return { text: "", recallOccurred: false, recallMinScore: resolvedPrio.recallMinScore };
169	    }
170	  }
171	
172	  if (entries.length === 0) {
173	    return { text: "", recallOccurred: false, recallMinScore: resolvedPrio.recallMinScore };
174	  }
175	
176	  // Apply type-weighted reranking and blocked filtering (Issue #121)
177	  const rankedRaw = rerankByTypeWeight(entries, resolvedPrio.recallTypeWeight, config.recallRecencyBoost, config.manualEntryBoost);
178	  const ranked = filterBlocked(rankedRaw, resolvedPrio.blocked);
179	
180	  // Build context string — progressive disclosure for large stores
181	  const compact = shouldUseCompactMode(ranked.length);
182	  let text = "## Active Memory (palaia)\n\n";
183	  if (compact) {
184	    text += "_Compact mode — use `memory_get <id>` for full details._\n\n";
185	  }
186	  let chars = text.length;
187	
188	  for (const entry of ranked) {
189	    const line = formatEntryLine(entry, compact);
190	    if (chars + line.length > effectiveMaxChars) break;
191	    text += line;
192	    chars += line.length;
193	  }
194	
195	  // Build nudge text and check remaining budget before appending
196	  const USAGE_NUDGE = "[palaia] auto-capture=on. Manual writes rank higher in recall. Use --type process for reusable workflows, --type task for sticky-note reminders (auto-deleted when done), --type memory for important facts.";
197	  let agentNudges = "";
198	  try {
199	    const pluginState = await loadPluginState(config.workspace);
200	    pluginState.successfulRecalls++;
201	    if (!pluginState.firstRecallTimestamp) {
202	      pluginState.firstRecallTimestamp = new Date().toISOString();
203	    }
204	    const { nudges } = checkNudges(pluginState);
205	    if (nudges.length > 0) {
206	      agentNudges = "\n\n## Agent Nudge (palaia)\n\n" + nudges.join("\n\n");
207	    }
208	    await savePluginState(pluginState, config.workspace);
209	  } catch {
210	    // Non-fatal
211	  }
212	
213	  // --- Isolation workflow nudges (#148) ---
214	  let isolationNudges = "";
215	
216	  // 1. missing_agent_identity: scopeVisibility configured but no PALAIA_AGENT
217	  if (resolvedPrio.scopeVisibility && !process.env.PALAIA_AGENT) {
218	    isolationNudges += "\n\n⚠️ scopeVisibility is configured but PALAIA_AGENT is not set. " +
219	      "Scope filtering cannot work without agent identity. Set PALAIA_AGENT env var.";
220	  }
221	
222	  // 2. recall_noise_ratio: >80% auto-capture entries for isolated agents
223	  if (resolvedPrio.scopeVisibility && ranked.length >= 5) {
224	    const autoCaptureCount = ranked.filter(e =>
225	      (e.tags || []).includes("auto-capture")
226	    ).length;
227	    if (autoCaptureCount / ranked.length > 0.8) {
228	      isolationNudges += "\n\n[palaia] Most recall results are auto-captured session data. " +
229	        "Ask the orchestrator to run: palaia prune --agent " +
230	        (process.env.PALAIA_AGENT || "<agent>") +
231	        " --tags auto-capture --protect-type process";
232	    }
233	  }
234	
235	  const nudgeText = USAGE_NUDGE + "\n\n" + agentNudges + isolationNudges;
236	  if (chars + nudgeText.length <= effectiveMaxChars) {
237	    text += nudgeText;
238	  }
239	
240	  const recallOccurred = entries.some(
241	    (e) => typeof e.score === "number" && e.score >= resolvedPrio.recallMinScore,
242	  );
243	
244	  return { text, recallOccurred, recallMinScore: resolvedPrio.recallMinScore };
245	}
