247	/**
248	 * Run auto-capture logic on a set of messages.
249	 * Used by the ContextEngine afterTurn() method.
250	 */
251	async function runAutoCapture(
252	  messages: unknown[],
253	  api: OpenClawPluginApi,
254	  config: PalaiaPluginConfig,
255	  logger: { info(...a: unknown[]): void; warn(...a: unknown[]): void },
256	): Promise<boolean> {
257	  if (!config.autoCapture) return false;
258	  if (!messages || messages.length === 0) {
259	    logger.info("[palaia] Auto-capture skipped: no messages");
260	    return false;
261	  }
262	
263	  const allTexts = extractMessageTexts(messages);
264	  const userTurns = allTexts.filter((t) => t.role === "user").length;
265	  if (userTurns < config.captureMinTurns) {
266	    logger.info(`[palaia] Auto-capture skipped: ${userTurns} user turns < captureMinTurns=${config.captureMinTurns}`);
267	    return false;
268	  }
269	
270	  // Parse capture hints
271	  const collectedHints: { project?: string; scope?: string }[] = [];
272	  for (const t of allTexts) {
273	    const { hints } = parsePalaiaHints(t.text);
274	    collectedHints.push(...hints);
275	  }
276	
277	  // Strip injected context and private blocks, then trim to recent
278	  const cleanedTexts = allTexts.map(t => ({
279	    ...t,
280	    text: stripPrivateBlocks(
281	      t.role === "user" ? strippalaiaInjectedContext(t.text) : t.text
282	    ),
283	  }));
284	  const recentTexts = trimToRecentExchanges(cleanedTexts);
285	  const exchangeParts: string[] = [];
286	  for (const t of recentTexts) {
287	    const { cleanedText } = parsePalaiaHints(t.text);
288	    exchangeParts.push(`[${t.role}]: ${cleanedText}`);
289	  }
290	  const exchangeText = exchangeParts.join("\n");
291	
292	  if (!shouldAttemptCapture(exchangeText)) {
293	    logger.info(`[palaia] Auto-capture skipped: content did not pass significance filter (${exchangeText.length} chars)`);
294	    return false;
295	  }
296	
297	  const hookOpts = buildRunnerOpts(config);
298	  const knownProjects = await loadProjects(hookOpts);
299	  const agentName = process.env.PALAIA_AGENT || undefined;
300	  const effectiveCaptureScope = await getEffectiveCaptureScope(config);
301	
302	  // LLM-based extraction (primary)
303	  let llmHandled = false;
304	  try {
305	    const results = await extractWithLLM(messages, api.config, {
306	      captureModel: config.captureModel,
307	      workspace: config.workspace,
308	    }, knownProjects);
309	
310	    for (const r of results) {
311	      if (r.significance >= config.captureMinSignificance) {
312	        const hintProject = collectedHints.find((h) => h.project)?.project;
313	        const hintScope = collectedHints.find((h) => h.scope)?.scope;
314	        const effectiveProject = hintProject || r.project;
315	        const scope = effectiveCaptureScope !== "team"
316	          ? sanitizeScope(effectiveCaptureScope, "team", true)
317	          : sanitizeScope(hintScope || r.scope, "team", false);
318	        const tags = [...r.tags];
319	        if (!tags.includes("auto-capture")) tags.push("auto-capture");
320	
321	        const args: string[] = [
322	          "write", r.content,
323	          "--type", r.type,
324	          "--tags", tags.join(",") || "auto-capture",
325	          "--scope", scope,
326	        ];
327	        const project = config.captureProject || effectiveProject;
328	        if (project) args.push("--project", project);
329	        if (agentName) args.push("--agent", agentName);
330	
331	        await run(args, { ...hookOpts, timeoutMs: 10_000 });
332	      }
333	    }
334	    llmHandled = true;
335	  } catch {
336	    // Fall through to rule-based
337	  }
338	
339	  // Rule-based fallback
340	  if (!llmHandled) {
341	    if (config.captureFrequency === "significant") {
342	      const significance = extractSignificance(exchangeText);
343	      if (!significance) {
344	        logger.info("[palaia] Auto-capture skipped: rule-based extraction found no significance (need ≥2 distinct tags)");
345	        return false;
346	      }
347	      const tags = [...significance.tags];
348	      if (!tags.includes("auto-capture")) tags.push("auto-capture");
349	      const scope = effectiveCaptureScope !== "team"
350	        ? sanitizeScope(effectiveCaptureScope, "team", true)
351	        : "team";
352	      const args: string[] = [
353	        "write", significance.summary,
354	        "--type", significance.type,
355	        "--tags", tags.join(","),
356	        "--scope", scope,
357	      ];
358	      if (agentName) args.push("--agent", agentName);
359	      await run(args, { ...hookOpts, timeoutMs: 10_000 });
360	    } else {
361	      const summary = exchangeParts.slice(-4).map(p => p.slice(0, 200)).join(" | ").slice(0, 500);
362	      const args: string[] = [
363	        "write", summary,
364	        "--type", "memory",
365	        "--tags", "auto-capture",
366	        "--scope", effectiveCaptureScope,
367	      ];
368	      if (agentName) args.push("--agent", agentName);
369	      await run(args, { ...hookOpts, timeoutMs: 10_000 });
370	    }
371	  }
372	
373	  return true;
374	}
