376	/**
377	 * Create a palaia ContextEngine implementing OpenClaw v2026.3.24 interface.
378	 */
379	export function createPalaiaContextEngine(
380	  api: OpenClawPluginApi,
381	  config: PalaiaPluginConfig,
382	): ContextEngine {
383	  const logger = api.logger;
384	  const opts = buildRunnerOpts(config);
385	
386	  /** Last messages seen via ingest(), used by assemble() for query building. */
387	  let _lastMessages: AgentMessage[] = [];
388	
389	  /** Whether the last assemble() call found relevant memories. */
390	  let _lastRecallOccurred = false;
391	
392	  const engine: ContextEngine = {
393	    info: {
394	      id: "palaia",
395	      name: "palaia Memory",
396	      version: "2.3",
397	      ownsCompaction: true,
398	    },
399	
400	    /**
401	     * Bootstrap: WAL recovery + embed-server start.
402	     */
403	    async bootstrap(_params) {
404	      try {
405	        const result = await recover(opts);
406	        if (result.replayed > 0) {
407	          logger.info(`[palaia] WAL recovery: replayed ${result.replayed} entries`);
408	        }
409	        if (result.errors > 0) {
410	          logger.warn(`[palaia] WAL recovery completed with ${result.errors} error(s)`);
411	        }
412	      } catch (error) {
413	        logger.warn(`[palaia] Bootstrap WAL recovery failed: ${error}`);
414	      }
415	
416	      // Pre-start embed server so first query is fast (~0.3s instead of ~3s)
417	      if (config.embeddingServer) {
418	        try {
419	          const mgr = getEmbedServerManager(opts);
420	          await mgr.start();
421	          logger.info("[palaia] Embed server started (pre-warmed for fast queries)");
422	        } catch (err) {
423	          logger.info(`[palaia] Embed server pre-start skipped: ${err}`);
424	        }
425	      }
426	
427	      return { bootstrapped: true };
428	    },
429	
430	    /**
431	     * Ingest: process a single message for auto-capture.
432	     * Called per-message by the ContextEngine lifecycle.
433	     * Accumulates messages; capture runs in afterTurn().
434	     */
435	    async ingest(params) {
436	      if (params.message) {
437	        _lastMessages.push(params.message);
438	      }
439	      return { ingested: true };
440	    },
441	
442	    /**
443	     * AfterTurn: run auto-capture on accumulated messages.
444	     */
445	    async afterTurn(params) {
446	      // Use params.messages if available (richer), else fall back to accumulated
447	      const messages = params?.messages?.length ? params.messages : _lastMessages;
448	
449	      try {
450	        await runAutoCapture(messages, api, config, logger);
451	      } catch (error) {
452	        logger.warn(`[palaia] ContextEngine afterTurn capture failed: ${error}`);
453	      }
454	
455	      // Reset for next turn
456	      _lastRecallOccurred = false;
457	      _lastMessages = [];
458	    },
459	
460	    /**
461	     * Assemble: recall logic with token budget awareness.
462	     * Returns memory context via systemPromptAddition.
463	     */
464	    async assemble(params) {
465	      _lastRecallOccurred = false;
466	
467	      if (!config.memoryInject) {
468	        return {
469	          messages: params.messages || [],
470	          estimatedTokens: 0,
471	        };
472	      }
473	
474	      try {
475	        const tokenBudget = params.tokenBudget || 4000;
476	        const maxChars = tokenBudget * 4;
477	
478	        // Use params.messages for query building (richer than accumulated)
479	        const queryMessages = params.messages?.length ? params.messages : _lastMessages;
480	
481	        const { text, recallOccurred } = await buildMemoryContext(
482	          config, opts, queryMessages, maxChars,
483	        );
484	
485	        _lastRecallOccurred = recallOccurred;
486	
487	        // Inject session briefing if pending (session_start or model switch)
488	        let briefingText = "";
489	        if (config.sessionBriefing && params.sessionKey) {
490	          const sessionState = getOrCreateSessionState(params.sessionKey);
491	          if (sessionState.pendingBriefing && !sessionState.briefingDelivered) {
492	            // Wait for briefing to be ready (with timeout)
493	            if (sessionState.briefingReady) {
494	              await Promise.race([
495	                sessionState.briefingReady,
496	                new Promise<void>(r => setTimeout(r, 3000)),
497	              ]);
498	            }
499	            if (sessionState.pendingBriefing) {
500	              const remainingChars = maxChars - (text?.length || 0);
501	              briefingText = formatBriefing(
502	                sessionState.pendingBriefing,
503	                Math.min(config.sessionBriefingMaxChars || 1500, remainingChars),
504	              );
505	              if (briefingText) {
506	                sessionState.briefingDelivered = true;
507	              }
508	            }
509	          }
510	        }
511	
512	        const combined = [briefingText, text].filter(Boolean).join("\n\n");
513	
514	        if (!combined) {
515	          return {
516	            messages: params.messages || [],
517	            estimatedTokens: 0,
518	          };
519	        }
520	
521	        return {
522	          messages: params.messages || [],
523	          estimatedTokens: estimateTokens(combined),
524	          systemPromptAddition: combined,
525	        };
526	      } catch (error) {
527	        logger.warn(`[palaia] ContextEngine assemble failed: ${error}`);
528	        return {
529	          messages: params.messages || [],
530	          estimatedTokens: 0,
531	        };
532	      }
533	    },
534	
535	    /**
536	     * Compact: trigger `palaia gc` via runner.
537	     */
538	    async compact(_params) {
539	      try {
540	        await run(["gc"], { ...opts, timeoutMs: 30_000 });
541	        logger.info("[palaia] GC compaction completed");
542	        return { ok: true, compacted: true };
543	      } catch (error) {
544	        logger.warn(`[palaia] GC compaction failed: ${error}`);
545	        return { ok: false, compacted: false, reason: String(error) };
546	      }
547	    },
548	
549	    /**
550	     * PrepareSubagentSpawn: load session summary for sub-agent context.
551	     */
552	    async prepareSubagentSpawn(_params) {
553	      // Sub-agents share the same palaia store via workspace,
554	      // so no explicit context passing is needed.
555	      // Future: use OpenClaw's extraSystemPrompt to pass session summary.
556	      return undefined;
557	    },
558	
559	    /**
560	     * OnSubagentEnded: capture sub-agent result as memory.
561	     */
562	    async onSubagentEnded(params) {
563	      if (!config.autoCapture) return;
564	      // Only capture results for successfully completed sub-agents
565	      if (params?.reason !== "completed") return;
566	      try {
567	        // Try to get sub-agent's last messages for summary
568	        if (api.runtime?.subagent?.getSessionMessages && params?.childSessionKey) {
569	          const result = await api.runtime.subagent.getSessionMessages({
570	            sessionKey: params.childSessionKey,
571	            limit: 10,
572	          });
573	          if (result?.messages?.length) {
574	            const texts = extractMessageTexts(result.messages);
575	            const summaryParts = texts.slice(-4).map(
576	              (t: { role: string; text: string }) => `[${t.role}]: ${t.text.slice(0, 200)}`
577	            );
578	            if (summaryParts.length > 0) {
579	              const summaryText = `Sub-agent result:\n${summaryParts.join("\n")}`.slice(0, 500);
580	              const subagentScope = await getEffectiveCaptureScope(config);
581	              await run([
582	                "write", summaryText,
583	                "--type", "memory",
584	                "--tags", "subagent-result,auto-capture",
585	                "--scope", subagentScope,
586	              ], { ...opts, timeoutMs: 10_000 });
587	              logger.info(`[palaia] Sub-agent result captured (${summaryText.length} chars)`);
588	            }
589	          }
590	        }
591	      } catch (error) {
592	        logger.warn(`[palaia] Sub-agent result capture failed: ${error}`);
593	      }
594	    },
595	  };
596	
597	  return engine;
598	}
