185	/**
186	 * Register lifecycle hooks on the plugin API.
187	 */
188	export function registerHooks(api: OpenClawPluginApi, config: PalaiaPluginConfig): void {
189	  // Store api.logger for module-wide use (integrates into OpenClaw log system)
190	  if (api.logger && typeof api.logger.info === "function") {
191	    logger = api.logger;
192	    setCaptureLogger(api.logger);
193	    setReactionsLogger(api.logger);
194	  }
195	
196	  const opts = buildRunnerOpts(config);
197	
198	  // Note: Session lifecycle hooks (session_start, session_end, before_reset,
199	  // llm_input, llm_output, after_tool_call) are registered in index.ts entry
200	  // point BEFORE this function, so they work for both ContextEngine and legacy paths.
201	
202	  // ── Startup checks (H-2, H-3, captureModel validation) ────────
203	  (async () => {
204	    // H-2: Warn if no agent is configured
205	    if (!process.env.PALAIA_AGENT) {
206	      try {
207	        const statusOut = await run(["config", "get", "agent"], { ...opts, timeoutMs: 3000 });
208	        if (!statusOut.trim()) {
209	          logger.warn(
210	            "[palaia] No agent configured. Set PALAIA_AGENT env var or run 'palaia init --agent <name>'. " +
211	            "Auto-captured entries will have no agent attribution."
212	          );
213	        }
214	      } catch {
215	        logger.warn(
216	          "[palaia] No agent configured. Set PALAIA_AGENT env var or run 'palaia init --agent <name>'. " +
217	          "Auto-captured entries will have no agent attribution."
218	        );
219	      }
220	    }
221	
222	    // H-3: Warn if no embedding provider beyond BM25
223	    try {
224	      const statusJson = await run(["status", "--json"], { ...opts, timeoutMs: 5000 });
225	      if (statusJson && statusJson.trim()) {
226	        const status = JSON.parse(statusJson);
227	        // embedding_chain can be at top level OR nested under config
228	        const chain = status.embedding_chain
229	          || status.embeddingChain
230	          || status.config?.embedding_chain
231	          || status.config?.embeddingChain
232	          || [];
233	        const hasSemanticProvider = Array.isArray(chain)
234	          ? chain.some((p: string) => p !== "bm25")
235	          : false;
236	        // Also check embedding_provider as a fallback signal
237	        const hasProviderConfig = !!(
238	          status.embedding_provider
239	          || status.config?.embedding_provider
240	        );
241	        if (!hasSemanticProvider && !hasProviderConfig) {
242	          logger.warn(
243	            "[palaia] No embedding provider configured. Semantic search is inactive (BM25 keyword-only). " +
244	            "Run 'pip install palaia[fastembed]' and 'palaia doctor --fix' for better recall quality."
245	          );
246	        }
247	      }
248	      // If statusJson is empty/null, skip warning (CLI may not be available)
249	    } catch {
250	      // Non-fatal — status check failed, skip warning (avoid false positive)
251	    }
252	
253	    // Pre-start embed server so first query is fast (~0.3s instead of ~3s)
254	    if (config.embeddingServer) {
255	      try {
256	        const mgr = getEmbedServerManager(opts);
257	        await mgr.start();
258	        logger.info("[palaia] Embed server started (pre-warmed for fast queries)");
259	      } catch (err) {
260	        logger.info(`[palaia] Embed server pre-start skipped: ${err}`);
261	      }
262	    }
263	
264	    // Validate captureModel auth at plugin startup via modelAuth API
265	    if (config.captureModel && api.runtime?.modelAuth) {
266	      try {
267	        const resolved = resolveCaptureModel(api.config, config.captureModel);
268	        if (resolved?.provider) {
269	          const key = await api.runtime.modelAuth.resolveApiKeyForProvider({ provider: resolved.provider, cfg: api.config });
270	          if (!key) {
271	            logger.warn(`[palaia] captureModel provider "${resolved.provider}" has no API key — auto-capture LLM extraction will fail`);
272	          }
273	        }
274	      } catch { /* non-fatal */ }
275	    }
276	  })();
277	
278	  // ── /palaia status command ─────────────────────────────────────
279	  api.registerCommand({
280	    name: "palaia-status",
281	    description: "Show palaia memory status",
282	    async handler(_args: string) {
283	      try {
284	        const state = await loadPluginState(config.workspace);
285	
286	        let stats: Record<string, unknown> = {};
287	        try {
288	          const statsOutput = await run(["status", "--json"], opts);
289	          stats = JSON.parse(statsOutput || "{}");
290	        } catch {
291	          // Non-fatal
292	        }
293	
294	        return { text: formatStatusResponse(state, stats, config) };
295	      } catch (error) {
296	        return { text: `palaia status error: ${error}` };
297	      }
298	    },
299	  });
