338	  // ── before_prompt_build (Issue #65: Query-based Recall + v3.0 Session Briefing) ──
339	  if (config.memoryInject) {
340	    api.on("before_prompt_build", async (event: any, ctx: any) => {
341	      // Prune stale entries to prevent memory leaks from crashed sessions (C-2)
342	      pruneStaleEntries();
343	
344	      // Per-agent workspace resolution (Issue #111)
345	      const resolved = resolvePerAgentContext(ctx, config);
346	      const hookOpts = buildRunnerOpts(config, { workspace: resolved.workspace });
347	
348	      try {
349	        // ── Session Briefing Injection (v3.0) ─────────────────────
350	        // If a session briefing is pending (from session_start or model switch),
351	        // prepend it to the recall context for seamless session continuity.
352	        let briefingText = "";
353	        let briefingSummary: string | null = null; // Kept for smart query fallback
354	        const sessionKey = resolveSessionKeyFromCtx(ctx);
355	        if (sessionKey) {
356	          const sessState = getOrCreateSessionState(sessionKey);
357	          // Wait for session_start briefing load (max 3s to avoid blocking)
358	          if (sessState.briefingReady) {
359	            await Promise.race([
360	              sessState.briefingReady,
361	              new Promise<void>(r => setTimeout(r, 3000)),
362	            ]);
363	          }
364	          // Capture summary BEFORE clearing, for smart query fallback below
365	          briefingSummary = sessState.pendingBriefing?.summary ?? null;
366	          if (sessState.pendingBriefing && !sessState.briefingDelivered) {
367	            briefingText = formatBriefing(sessState.pendingBriefing, config.sessionBriefingMaxChars);
368	            sessState.briefingDelivered = true;
369	            // Clear pending briefing after delivery (unless model switch re-triggers)
370	            if (!sessState.modelSwitchDetected) {
371	              sessState.pendingBriefing = null;
372	            }
373	            sessState.modelSwitchDetected = false;
374	          }
375	        }
376	
377	        // Load and resolve priorities (Issue #121)
378	        const prio = await loadPriorities(resolved.workspace);
379	        const project = config.captureProject || undefined;
380	        const resolvedPrio = resolvePriorities(prio, {
381	          recallTypeWeight: config.recallTypeWeight,
382	          recallMinScore: config.recallMinScore,
383	          maxInjectedChars: config.maxInjectedChars,
384	          tier: config.tier,
385	        }, resolved.agentId, project);
386	
387	        // Reduce recall budget by briefing size
388	        const maxChars = Math.max((resolvedPrio.maxInjectedChars || 4000) - briefingText.length, 500);
389	        const limit = Math.min(config.maxResults || 10, 20);
390	        let entries: QueryResult["results"] = [];
391	
392	        if (config.recallMode === "query") {
393	          let userMessage = event.messages
394	            ? buildRecallQuery(event.messages)
395	            : (event.prompt || null);
396	
397	          // ── Smart Query Fallback (v3.0) ───────────────────────
398	          // If query is too short or matches a continuation pattern,
399	          // use the session summary as query for better recall results.
400	          const CONTINUATION_PATTERN = /^(ja|ok|weiter|mach|genau|do it|yes|continue|go|proceed|sure|klar|passt|yep|yup|exactly|right)\b/i;
401	          if (briefingSummary && userMessage && (userMessage.length < 10 || CONTINUATION_PATTERN.test(userMessage.trim()))) {
402	            userMessage = briefingSummary.slice(0, 500);
403	            logger.info("[palaia] Smart query fallback: using session summary as recall query");
404	          }
405	
406	          if (userMessage && userMessage.length >= 5) {
407	            // Try embed server first (fast path: ~0.5s), then CLI fallback (~3-14s)
408	            let serverQueried = false;
409	            if (config.embeddingServer) {
410	              try {
411	                const mgr = getEmbedServerManager(hookOpts);
412	                // If embed server workspace differs from resolved workspace, skip server and use CLI
413	                const serverWorkspace = hookOpts.workspace;
414	                const embedOpts = buildRunnerOpts(config);
415	                if (serverWorkspace !== embedOpts.workspace) {
416	                  logger.info(`[palaia] Embed server workspace mismatch (agent=${resolved.workspace}), falling back to CLI`);
417	                } else {
418	                  const resp = await mgr.query({
419	                    text: userMessage,
420	                    top_k: limit,
421	                    include_cold: resolvedPrio.tier === "all",
422	                    ...(resolvedPrio.scopeVisibility ? { scope_visibility: resolvedPrio.scopeVisibility } : {}),
423	                  }, config.timeoutMs || 3000);
424	                  if (resp?.result?.results && Array.isArray(resp.result.results)) {
425	                    entries = resp.result.results;
426	                    serverQueried = true;
427	                  }
428	                }
429	              } catch (serverError) {
430	                logger.warn(`[palaia] Embed server query failed, falling back to CLI: ${serverError}`);
431	              }
432	            }
433	
434	            // CLI fallback
435	            if (!serverQueried) {
436	              try {
437	                const queryArgs: string[] = ["query", userMessage, "--limit", String(limit)];
438	                if (resolvedPrio.tier === "all") {
439	                  queryArgs.push("--all");
440	                }
441	                const result = await runJson<QueryResult>(queryArgs, { ...hookOpts, timeoutMs: 15000 });
442	                if (result && Array.isArray(result.results)) {
443	                  entries = result.results;
444	                }
445	              } catch (queryError) {
446	                logger.warn(`[palaia] Query recall failed, falling back to list: ${queryError}`);
447	              }
448	            }
449	          }
450	        }
451	
452	        // Fallback: list mode (no emoji — list-based recall is not query-relevant)
453	        let isListFallback = false;
454	        if (entries.length === 0) {
455	          isListFallback = true;
456	          try {
457	            const listArgs: string[] = ["list"];
458	            if (resolvedPrio.tier === "all") {
459	              listArgs.push("--all");
460	            } else {
461	              listArgs.push("--tier", resolvedPrio.tier || "hot");
462	            }
463	            const result = await runJson<QueryResult>(listArgs, hookOpts);
464	            if (result && Array.isArray(result.results)) {
465	              entries = result.results;
466	            }
467	          } catch {
468	            // Still deliver briefing even if recall fails completely
469	            if (briefingText) {
470	              return { prependContext: briefingText };
471	            }
472	            return;
473	          }
474	        }
475	
476	        // If no recall entries but briefing exists, deliver briefing alone
477	        if (entries.length === 0) {
478	          if (briefingText) {
479	            return { prependContext: briefingText };
480	          }
481	          return;
482	        }
483	
484	        // Apply type-weighted reranking and blocked filtering (Issue #121)
485	        const rankedRaw = rerankByTypeWeight(entries, resolvedPrio.recallTypeWeight, config.recallRecencyBoost, config.manualEntryBoost);
486	        const ranked = filterBlocked(rankedRaw, resolvedPrio.blocked);
487	
488	        // Build context string with char budget
489	        // Progressive disclosure: compact mode for large stores (title + first line + ID)
490	        const compact = shouldUseCompactMode(ranked.length);
491	        let text = "## Active Memory (palaia)\n\n";
492	        if (compact) {
493	          text += "_Compact mode — use `memory_get <id>` for full details._\n\n";
494	        }
495	        let chars = text.length;
496	
497	        for (const entry of ranked) {
498	          const line = formatEntryLine(entry, compact);
499	          if (chars + line.length > maxChars) break;
500	          text += line;
501	          chars += line.length;
502	        }
503	
504	        // Build nudge text and check remaining budget before appending
505	        const USAGE_NUDGE = "[palaia] auto-capture=on. Manual write: --type process (SOPs/checklists) or --type task (todos with assignee/deadline) only. Conversation knowledge is auto-captured — do not duplicate with manual writes.";
506	        let nudgeContext = "";
507	        try {
508	          const pluginState = await loadPluginState(resolved.workspace);
509	          pluginState.successfulRecalls++;
510	          if (!pluginState.firstRecallTimestamp) {
511	            pluginState.firstRecallTimestamp = new Date().toISOString();
512	          }
513	          const { nudges } = checkNudges(pluginState);
514	          if (nudges.length > 0) {
515	            nudgeContext = "\n\n## Agent Nudge (palaia)\n\n" + nudges.join("\n\n");
516	          }
517	          await savePluginState(pluginState, resolved.workspace);
518	        } catch {
519	          // Non-fatal
520	        }
521	
522	        // Before adding nudges, check remaining budget
523	        const nudgeText = USAGE_NUDGE + "\n\n" + nudgeContext;
524	        if (chars + nudgeText.length <= maxChars) {
525	          text += nudgeText;
526	        }
527	        // If nudges don't fit, skip them — the recall content is more important
528	
529	        // Track recall in session-isolated turn state for emoji reactions
530	        // Only flag recall as meaningful if at least one result scores above threshold
531	        // List-fallback never triggers brain emoji (not query-relevant)
532	        const hasRelevantRecall = !isListFallback && entries.some(
533	          (e) => typeof e.score === "number" && e.score >= resolvedPrio.recallMinScore,
534	        );
535	        if (sessionKey && hasRelevantRecall) {
536	          const turnState = getOrCreateTurnState(sessionKey);
537	          turnState.recallOccurred = true;
538	
539	          // Populate channel info — prefer event metadata, fall back to sessionKey
540	          const provider = extractChannelFromSessionKey(sessionKey);
541	          if (provider) turnState.channelProvider = provider;
542	          const slackChannel = extractChannelIdFromEvent(event, ctx)
543	            ?? extractSlackChannelIdFromSessionKey(sessionKey);
544	          if (slackChannel) turnState.lastInboundChannelId = slackChannel;
545	
546	          // Try to get the inbound message ID from the message_received store
547	          if (slackChannel) {
548	            const inbound = lastInboundMessageByChannel.get(slackChannel);
549	            if (inbound && (Date.now() - inbound.timestamp) < 30_000) {
550	              turnState.lastInboundMessageId = inbound.messageId;
551	            }
552	          }
553	        }
554	
555	        // Return prependContext + appendSystemContext for recall emoji
556	        return {
557	          prependContext: briefingText + text,
558	          appendSystemContext: config.showMemorySources
559	            ? "You used palaia memory in this turn. Add \u{1f9e0} at the very end of your response (after everything else, on its own line)."
560	            : undefined,
561	        };
562	      } catch (error) {
563	        logger.warn(`[palaia] Memory injection failed: ${error}`);
564	      }
565	    });
566	  }
