568	  // ── message_sending (Issue #81: Hint stripping) ──────────────────
569	  api.on("message_sending", (_event: any, _ctx: any) => {
570	    const content = _event?.content;
571	    if (typeof content !== "string") return;
572	
573	    const { hints, cleanedText } = parsePalaiaHints(content);
574	    if (hints.length > 0) {
