579	  // ── agent_end (Issue #64 + #81: Auto-Capture with Metadata + Reactions) ───
580	  if (config.autoCapture) {
581	    api.on("agent_end", async (event: any, ctx: any) => {
582	      // Resolve session key for turn state
583	      const sessionKey = resolveSessionKeyFromCtx(ctx);
584	
585	      // Per-agent workspace resolution (Issue #111)
586	      const resolved = resolvePerAgentContext(ctx, config);
587	      const hookOpts = buildRunnerOpts(config, { workspace: resolved.workspace });
588	
589	      if (!event.success || !event.messages || event.messages.length === 0) {
590	        logger.info(`[palaia] Auto-capture skipped: success=${event.success}, messages=${event.messages?.length ?? 0}`);
591	        return;
592	      }
593	
594	      try {
595	        const agentName = resolved.agentId;
596	
597	        const allTexts = extractMessageTexts(event.messages);
598	
599	        const userTurns = allTexts.filter((t) => t.role === "user").length;
600	        if (userTurns < config.captureMinTurns) {
601	          logger.info(`[palaia] Auto-capture skipped: ${userTurns} user turns < captureMinTurns=${config.captureMinTurns}`);
602	          return;
603	        }
604	
605	        // Parse capture hints from all messages (Issue #81)
606	        const collectedHints: PalaiaHint[] = [];
607	        for (const t of allTexts) {
608	          const { hints } = parsePalaiaHints(t.text);
609	          collectedHints.push(...hints);
610	        }
611	
612	        // Strip palaia-injected recall context and private blocks from messages.
613	        // The recall block is prepended to user messages by before_prompt_build.
614	        // Without stripping, auto-capture would re-capture previously recalled memories.
615	        // Private blocks (<private>...</private>) must be excluded from capture.
616	        const { stripPrivateBlocks } = await import("./capture.js");
617	        const cleanedTexts = allTexts.map(t => ({
618	          ...t,
619	          text: stripPrivateBlocks(
620	            t.role === "user" ? strippalaiaInjectedContext(t.text) : t.text
621	          ),
622	        }));
623	
624	        // Only extract from recent exchanges — full history causes LLM timeouts
625	        // and dilutes extraction quality
626	        const recentTexts = trimToRecentExchanges(cleanedTexts);
627	
628	        // Build exchange text from recent window only
629	        const exchangeParts: string[] = [];
630	        for (const t of recentTexts) {
631	          const { cleanedText } = parsePalaiaHints(t.text);
632	          exchangeParts.push(`[${t.role}]: ${cleanedText}`);
633	        }
634	        const exchangeText = exchangeParts.join("\n");
635	
636	        if (!shouldAttemptCapture(exchangeText)) {
637	          logger.info(`[palaia] Auto-capture skipped: content did not pass significance filter (${exchangeText.length} chars)`);
638	          return;
639	        }
640	
641	        const knownProjects = await loadProjects(hookOpts);
642	
643	        // Resolve effective capture scope from priorities (per-agent override, #147)
644	        let effectiveCaptureScope = config.captureScope || "";
645	        try {
646	          const prio = await loadPriorities(resolved.workspace);
647	          const resolvedCapturePrio = resolvePriorities(prio, {
648	            recallTypeWeight: config.recallTypeWeight,
649	            recallMinScore: config.recallMinScore,
650	            maxInjectedChars: config.maxInjectedChars,
651	            tier: config.tier,
652	          }, agentName);
653	          if (resolvedCapturePrio.captureScope) {
654	            effectiveCaptureScope = resolvedCapturePrio.captureScope;
655	          }
656	        } catch {
657	          // Fall through to config default
658	        }
659	
660	        // Helper: build CLI args with metadata
661	        const buildWriteArgs = (
662	          content: string,
663	          type: string,
664	          tags: string[],
665	          itemProject?: string | null,
666	          itemScope?: string | null,
667	        ): string[] => {
668	          const args: string[] = [
669	            "write",
670	            content,
671	            "--type", type,
672	            "--tags", tags.join(",") || "auto-capture",
673	          ];
674	
675	          // Scope guardrail: priorities captureScope > config.captureScope > hint/LLM scope
676	          const scope = effectiveCaptureScope
677	            ? sanitizeScope(effectiveCaptureScope, "team", true)
678	            : sanitizeScope(itemScope, "team", false);
679	          args.push("--scope", scope);
680	
681	          const project = config.captureProject || itemProject;
682	          if (project) {
683	            args.push("--project", project);
684	          }
685	
686	          if (agentName) {
687	            args.push("--agent", agentName);
688	          }
689	
690	          return args;
691	        };
692	
693	        // Helper: store LLM extraction results
694	        const storeLLMResults = async (results: ExtractionResult[]) => {
695	          for (const r of results) {
696	            if (r.significance >= config.captureMinSignificance) {
697	              const hintForProject = collectedHints.find((h) => h.project);
698	              const hintForScope = collectedHints.find((h) => h.scope);
699	
700	              const effectiveProject = hintForProject?.project || r.project;
701	              const effectiveScope = hintForScope?.scope || r.scope;
702	
703	              // Project validation: reject unknown projects
704	              let validatedProject = effectiveProject;
705	              if (validatedProject && knownProjects.length > 0) {
706	                const isKnown = knownProjects.some(
707	                  (p) => p.name.toLowerCase() === validatedProject!.toLowerCase(),
708	                );
709	                if (!isKnown) {
710	                  logger.info(`[palaia] Auto-capture: unknown project "${validatedProject}" ignored`);
711	                  validatedProject = null;
712	                }
713	              }
714	
715	              // Always include auto-capture tag for GC identification
716	              const tags = [...r.tags];
717	              if (!tags.includes("auto-capture")) tags.push("auto-capture");
718	
719	              const args = buildWriteArgs(
720	                r.content,
721	                r.type,
722	                tags,
723	                validatedProject,
724	                effectiveScope,
725	              );
726	              await run(args, { ...hookOpts, timeoutMs: 10_000 });
727	              logger.info(
728	                `[palaia] LLM auto-captured: type=${r.type}, significance=${r.significance}, tags=${tags.join(",")}, project=${validatedProject || "none"}, scope=${effectiveScope || "team"}`
729	              );
730	            }
731	          }
732	        };
733	
734	        // LLM-based extraction (primary)
735	        let llmHandled = false;
736	        try {
737	          const results = await extractWithLLM(event.messages, api.config, {
738	            captureModel: config.captureModel,
739	            workspace: resolved.workspace,
740	          }, knownProjects);
741	
742	          await storeLLMResults(results);
743	          llmHandled = true;
744	        } catch (llmError) {
745	          // Check if this is a model-availability error (not a generic import failure)
746	          const errStr = String(llmError);
747	          const isModelError = /FailoverError|Unknown model|unknown model|401|403|model.*not found|not_found|model_not_found/i.test(errStr);
748	
749	          if (isModelError && config.captureModel) {
750	            // captureModel is broken — try primary model as fallback
751	            if (!getCaptureModelFailoverWarned()) {
752	              setCaptureModelFailoverWarned(true);
