19	/** Parsed palaia-hint tag attributes */
20	export interface PalaiaHint {
21	  project?: string;
22	  scope?: string;
23	  type?: string;
24	  tags?: string[];
25	}
26	
27	/**
28	 * Parse `<palaia-hint ... />` tags from text.
29	 * Returns extracted hints and cleaned text with hints removed.
30	 */
31	export function parsePalaiaHints(text: string): { hints: PalaiaHint[]; cleanedText: string } {
32	  const hints: PalaiaHint[] = [];
33	  const regex = /<palaia-hint\s+([^/]*)\s*\/>/gi;
34	
35	  let match: RegExpExecArray | null;
36	  while ((match = regex.exec(text)) !== null) {
37	    const attrs = match[1];
38	    const hint: PalaiaHint = {};
39	
40	    const projectMatch = attrs.match(/project\s*=\s*"([^"]*)"/i);
41	    if (projectMatch) hint.project = projectMatch[1];
42	
43	    const scopeMatch = attrs.match(/scope\s*=\s*"([^"]*)"/i);
44	    if (scopeMatch) hint.scope = scopeMatch[1];
45	
46	    const typeMatch = attrs.match(/type\s*=\s*"([^"]*)"/i);
47	    if (typeMatch) hint.type = typeMatch[1];
48	
49	    const tagsMatch = attrs.match(/tags\s*=\s*"([^"]*)"/i);
50	    if (tagsMatch) hint.tags = tagsMatch[1].split(",").map((t) => t.trim()).filter(Boolean);
51	
52	    hints.push(hint);
53	  }
54	
55	  const cleanedText = text.replace(/<palaia-hint\s+[^/]*\s*\/>/gi, "").trim();
56	  return { hints, cleanedText };
57	}
