124	/**
125	 * Resolve the path to OpenClaw's extensionAPI module.
126	 * Uses multiple strategies for portability across installation layouts.
127	 */
128	function resolveExtensionAPIPath(): string | null {
129	  // Strategy 1: require.resolve with openclaw package exports
130	  try {
131	    return require.resolve("openclaw/dist/extensionAPI.js");
132	  } catch {
133	    // Not resolvable via standard module resolution
134	  }
135	
136	  // Strategy 2: Resolve openclaw main entry, then navigate to dist/extensionAPI.js
137	  try {
138	    const openclawMain = require.resolve("openclaw");
139	    const candidate = path.join(path.dirname(openclawMain), "extensionAPI.js");
140	    if (require("node:fs").existsSync(candidate)) return candidate;
141	  } catch {
142	    // openclaw not resolvable at all
143	  }
144	
145	  // Strategy 3: Sibling in global node_modules (plugin installed alongside openclaw)
146	  try {
147	    // __dirname is always available in CJS (our tsconfig module); the ESM
148	    // fallback via import.meta.url is kept for jiti/ESM loaders at runtime.
149	    // @ts-expect-error import.meta is valid at runtime under jiti/ESM but TS module=commonjs rejects it
150	    const thisFile: string = typeof __dirname !== "undefined" ? __dirname : path.dirname(new URL(import.meta.url).pathname);
151	    // Walk up from plugin src/dist to node_modules, then into openclaw
152	    let dir = thisFile;
153	    for (let i = 0; i < 6; i++) {
154	      const candidate = path.join(dir, "openclaw", "dist", "extensionAPI.js");
155	      if (require("node:fs").existsSync(candidate)) return candidate;
156	      const parent = path.dirname(dir);
157	      if (parent === dir) break;
158	      dir = parent;
159	    }
160	  } catch {
161	    // Traversal failed
162	  }
163	
164	  // Strategy 4: Well-known global install paths
165	  const globalCandidates = [
166	    path.join(os.homedir(), ".openclaw", "node_modules", "openclaw", "dist", "extensionAPI.js"),
167	    "/home/linuxbrew/.linuxbrew/lib/node_modules/openclaw/dist/extensionAPI.js",
168	    "/usr/local/lib/node_modules/openclaw/dist/extensionAPI.js",
169	    "/usr/lib/node_modules/openclaw/dist/extensionAPI.js",
170	  ];
171	  for (const candidate of globalCandidates) {
172	    try {
173	      if (require("node:fs").existsSync(candidate)) return candidate;
174	    } catch {
175	      // skip
176	    }
177	  }
178	
179	  return null;
180	}
