182	async function loadRunEmbeddedPiAgent(): Promise<RunEmbeddedPiAgentFn> {
183	  const resolved = resolveExtensionAPIPath();
184	  if (!resolved) {
185	    throw new Error("Could not locate openclaw/dist/extensionAPI.js — tried module resolution, sibling lookup, and global paths");
186	  }
187	
188	  const mod = (await import(resolved)) as { runEmbeddedPiAgent?: unknown };
189	  const fn = (mod as any).runEmbeddedPiAgent;
190	  if (typeof fn !== "function") {
191	    throw new Error(`runEmbeddedPiAgent not exported from ${resolved}`);
192	  }
193	  return fn as RunEmbeddedPiAgentFn;
194	}
