287	/**
288	 * Heuristic patterns to identify cheap/small models from their name.
289	 * Avoids hardcoded model IDs that go stale — instead matches naming
290	 * conventions that providers consistently use for their smaller tiers.
291	 *
292	 * Patterns are matched as word boundaries (separated by `-`, `.`, `/`,
293	 * or string edges) to avoid false positives like "ge*mini*" matching "mini".
294	 */
295	const CHEAP_MODEL_PATTERNS = [
296	  "haiku",     // Anthropic's smallest tier
297	  "flash",     // Google's smallest tier
298	  "mini",      // OpenAI's smallest tier (gpt-4o-mini, gpt-4.1-mini, ...)
299	  "small",     // Mistral's smallest tier
300	  "nano",      // Future small models
301	  "lite",      // Various providers
302	  "instant",   // Anthropic legacy
303	];
304	
305	/** Check if a model name matches any cheap pattern (word-boundary aware). */
306	function isCheapModel(modelName: string): boolean {
307	  const lower = modelName.toLowerCase();
308	  // Split on common separators: dash, dot, slash, underscore
309	  const parts = lower.split(/[-./_ ]/);
310	  return CHEAP_MODEL_PATTERNS.some((p) => parts.includes(p));
311	}
312	
313	/**
314	 * Resolve the model to use for LLM-based capture extraction.
315	 *
316	 * Strategy (prefer cheapest available model for cost efficiency):
317	 * 1. If captureModel is set explicitly (e.g. "anthropic/claude-haiku-4-5"): use it directly.
318	 * 2. If captureModel is "cheap" or unset: detect the primary model's provider,
319	 *    then pick the cheapest known model for that provider.
320	 * 3. If no cheap model is known for the provider, fall back to primary model
321	 *    with a one-time warning.
322	 */
323	export function resolveCaptureModel(
324	  config: any,
325	  captureModel?: string,
326	): { provider: string; model: string } | undefined {
327	  // Case 1: explicit model ID provided (not "cheap")
328	  if (captureModel && captureModel !== "cheap") {
329	    const parts = captureModel.split("/");
330	    if (parts.length >= 2) {
331	      return { provider: parts[0], model: parts.slice(1).join("/") };
332	    }
333	    // No slash — treat as model name with provider from primary config
334	    const defaultsModel = config?.agents?.defaults?.model;
335	    const primary = typeof defaultsModel === "string"
336	      ? defaultsModel.trim()
337	      : (defaultsModel?.primary?.trim() ?? "");
338	    const defaultProvider = primary.split("/")[0];
339	    if (defaultProvider) {
340	      return { provider: defaultProvider, model: captureModel };
341	    }
342	  }
343	
344	  // Case 2: "cheap" or unset — use primary model, but check if it's already cheap
345	  const defaultsModel = config?.agents?.defaults?.model;
346	
347	  const primary = typeof defaultsModel === "string"
348	    ? defaultsModel.trim()
349	    : (typeof defaultsModel === "object" && defaultsModel !== null
350	      ? String(defaultsModel.primary ?? "").trim()
351	      : "");
352	
353	  if (primary) {
354	    const parts = primary.split("/");
355	    if (parts.length >= 2) {
356	      const provider = parts[0];
357	      const modelName = parts.slice(1).join("/");
358	
359	      // Check if the primary model is already cheap (e.g., user runs haiku as main)
360	      if (isCheapModel(modelName)) {
361	        return { provider, model: modelName };
362	      }
363	
364	      // Primary is expensive — check if the runtime exposes available models
365	      // so we can pick a cheap one from the same provider dynamically.
366	      const runtimeModels: string[] = config?.runtime?.availableModels
367	        ?? config?.models
368	        ?? [];
369	      const cheapFromRuntime = runtimeModels.find((m: string) => {
370	        const lower = m.toLowerCase();
371	        return lower.startsWith(provider + "/") && isCheapModel(m);
372	      });
373	      if (cheapFromRuntime) {
374	        const rParts = cheapFromRuntime.split("/");
375	        return { provider: rParts[0], model: rParts.slice(1).join("/") };
376	      }
377	
378	      // No cheap alternative found — use primary model with one-time hint
379	      if (!_captureModelFallbackWarned) {
380	        _captureModelFallbackWarned = true;
381	        logger.warn(`[palaia] Using primary model for capture extraction. Set captureModel in plugin config (e.g. "anthropic/claude-haiku-4-5") for cost savings.`);
382	      }
383	      return { provider, model: modelName };
384	    }
385	  }
386	
387	  return undefined;
388	}
