390	function stripCodeFences(s: string): string {
391	  const trimmed = s.trim();
392	  const m = trimmed.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
393	  if (m) return (m[1] ?? "").trim();
394	  return trimmed;
395	}
