397	function collectText(payloads: Array<{ text?: string; isError?: boolean }> | undefined): string {
398	  return (payloads ?? [])
399	    .filter((p) => !p.isError && typeof p.text === "string")
400	    .map((p) => p.text ?? "")
401	    .join("\n")
402	    .trim();
403	}
