405	/**
406	 * Trim message texts to a recent window for LLM extraction.
407	 * Only extract from recent exchanges — full history causes LLM timeouts
408	 * and dilutes extraction quality.
409	 *
410	 * Strategy: keep last N user+assistant pairs (skip toolResult roles),
411	 * then hard-cap at maxChars from the end (newest messages kept).
412	 */
413	export function trimToRecentExchanges(
414	  texts: Array<{ role: string; text: string; provenance?: string }>,
415	  maxPairs = 5,
416	  maxChars = 10_000,
417	): Array<{ role: string; text: string; provenance?: string }> {
418	  // Filter to only user + assistant messages (skip tool, toolResult, system, etc.)
419	  const exchanges = texts.filter((t) => t.role === "user" || t.role === "assistant");
420	
421	  // Keep the last N pairs (a pair = one user + one assistant message)
422	  // Only count external_user messages as real user turns.
423	  // System-injected user messages (inter_session, internal_system) don't count as conversation turns.
424	  // Walk backwards, count pairs
425	  let pairCount = 0;
426	  let lastRole = "";
427	  let cutIndex = 0; // default: keep everything
428	  for (let i = exchanges.length - 1; i >= 0; i--) {
429	    const isRealUser = exchanges[i].role === "user" && (
430	      exchanges[i].provenance === "external_user" ||
431	      !exchanges[i].provenance // backward compat: no provenance = treat as real user
432	    );
433	    // Count a new pair when we see a real user message after having seen an assistant
434	    if (isRealUser && lastRole === "assistant") {
435	      pairCount++;
436	      if (pairCount > maxPairs) {
437	        cutIndex = i + 1; // keep from next message onwards
438	        break;
439	      }
440	    }
441	    if (exchanges[i].role !== lastRole) {
442	      lastRole = exchanges[i].role;
443	    }
444	  }
445	  let trimmed = exchanges.slice(cutIndex);
446	
447	  // Hard cap: max chars from the end (keep newest)
448	  let totalChars = trimmed.reduce((sum, t) => sum + t.text.length + t.role.length + 5, 0);
449	  while (totalChars > maxChars && trimmed.length > 1) {
450	    const removed = trimmed.shift()!;
451	    totalChars -= removed.text.length + removed.role.length + 5;
452	  }
453	
454	  return trimmed;
455	}
