457	export async function extractWithLLM(
458	  messages: unknown[],
459	  config: any,
460	  pluginConfig?: { captureModel?: string; workspace?: string },
461	  knownProjects?: CachedProject[],
462	): Promise<ExtractionResult[]> {
463	  const runEmbeddedPiAgent = await getEmbeddedPiAgent();
464	
465	  const resolved = resolveCaptureModel(config, pluginConfig?.captureModel);
466	  if (!resolved) {
467	    throw new Error("No model available for LLM extraction");
468	  }
469	
470	  const allTexts = extractMessageTexts(messages);
471	  // Strip palaia-injected recall context and private blocks from user messages
472	  const cleanedTexts = allTexts.map(t =>
473	    t.role === "user"
474	      ? { ...t, text: stripPrivateBlocks(strippalaiaInjectedContext(t.text)) }
475	      : { ...t, text: stripPrivateBlocks(t.text) }
476	  );
477	  // Only extract from recent exchanges — full history causes LLM timeouts
478	  // and dilutes extraction quality
479	  const recentTexts = trimToRecentExchanges(cleanedTexts);
480	  const exchangeText = recentTexts
481	    .map((t) => `[${t.role}]: ${t.text}`)
482	    .join("\n");
483	
484	  if (!exchangeText.trim()) {
485	    return [];
486	  }
487	
488	  const systemPrompt = buildExtractionPrompt(knownProjects || []);
489	  const prompt = `${systemPrompt}\n\n--- CONVERSATION ---\n${exchangeText}\n--- END ---`;
490	
491	  let tmpDir: string | null = null;
492	  try {
493	    // Use a fixed base directory for extraction temp dirs and clean up stale ones
494	    const extractBaseDir = path.join(os.tmpdir(), "palaia-extractions");
495	    await fs.mkdir(extractBaseDir, { recursive: true });
496	    // Clean up stale extraction dirs (older than 5 minutes)
497	    try {
498	      const entries = await fs.readdir(extractBaseDir, { withFileTypes: true });
499	      const now = Date.now();
500	      for (const entry of entries) {
501	        if (entry.isDirectory()) {
502	          try {
503	            const stat = await fs.stat(path.join(extractBaseDir, entry.name));
504	            if (now - stat.mtimeMs > 5 * 60 * 1000) {
505	              await fs.rm(path.join(extractBaseDir, entry.name), { recursive: true, force: true });
506	            }
507	          } catch { /* ignore individual cleanup errors */ }
508	        }
509	      }
510	    } catch { /* ignore cleanup errors */ }
511	    tmpDir = await fs.mkdtemp(path.join(extractBaseDir, "ext-"));
512	    const sessionId = `palaia-extract-${Date.now()}`;
513	    const sessionFile = path.join(tmpDir, "session.json");
514	
515	    const result = await runEmbeddedPiAgent({
516	      sessionId,
517	      sessionFile,
518	      workspaceDir: pluginConfig?.workspace || config?.agents?.defaults?.workspace || process.cwd(),
519	      config,
520	      prompt,
521	      timeoutMs: 15_000,
522	      runId: `palaia-extract-${Date.now()}`,
523	      provider: resolved.provider,
524	      model: resolved.model,
525	      disableTools: true,
526	      streamParams: { maxTokens: 2048 },
527	    });
528	
529	    const text = collectText((result as any).payloads);
530	    if (!text) return [];
531	
532	    const raw = stripCodeFences(text);
533	    let parsed: unknown;
534	    try {
535	      parsed = JSON.parse(raw);
536	    } catch {
537	      throw new Error(`LLM returned invalid JSON: ${raw.slice(0, 200)}`);
538	    }
539	
540	    if (!Array.isArray(parsed)) {
541	      throw new Error(`LLM returned non-array: ${typeof parsed}`);
542	    }
543	
544	    const results: ExtractionResult[] = [];
545	    for (const item of parsed) {
546	      if (!item || typeof item !== "object") continue;
547	      const content = typeof item.content === "string" ? item.content.trim() : "";
548	      if (!content) continue;
549	
550	      const validTypes = new Set(["memory", "process"]);
551	      // Tasks are manual-only (post-its) — auto-capture never creates tasks
552	      const type = validTypes.has(item.type) ? item.type : "memory";
553	
554	      const validTags = new Set([
555	        "decision", "lesson", "surprise", "commitment",
556	        "correction", "preference", "fact",
557	      ]);
558	      const tags = Array.isArray(item.tags)
559	        ? item.tags.filter((t: unknown) => typeof t === "string" && validTags.has(t))
560	        : [];
561	
562	      const significance = typeof item.significance === "number"
563	        ? Math.max(0, Math.min(1, item.significance))
564	        : 0.5;
565	
566	      const project = typeof item.project === "string" && item.project.trim()
567	        ? item.project.trim()
568	        : null;
569	
570	      const scope = typeof item.scope === "string" && isValidScope(item.scope)
571	        ? item.scope
572	        : null;
573	
574	      results.push({ content, type, tags, significance, project, scope });
575	    }
576	
577	    return results;
578	  } finally {
579	    if (tmpDir) {
580	      try { await fs.rm(tmpDir, { recursive: true, force: true }); } catch { /* ignore */ }
581	    }
582	  }
583	}
