628	const NOISE_PATTERNS: RegExp[] = [
629	  /(?:PASSED|FAILED|ERROR)\s+\[?\d+%\]?/i,
630	  /(?:test_\w+|tests?\/\w+\.(?:py|ts|js))\s*::/,
631	  /(?:pytest|vitest|jest|mocha)\s+(?:run|--)/i,
632	  /\d+ passed,?\s*\d* (?:failed|error|warning)/i,
633	  /^(?:=+\s*(?:test session|ERRORS|FAILURES|short test summary))/m,
634	  /(?:Traceback \(most recent call last\)|^\s+File ".*", line \d+)/m,
635	  /^\s+at\s+\S+\s+\(.*:\d+:\d+\)/m,
636	  /^(?:\/[\w/.-]+){3,}\s*$/m,
637	  /(?:npm\s+(?:ERR|WARN)|pip\s+install|cargo\s+build)/i,
638	  /^(?:warning|error)\[?\w*\]?:\s/m,
639	];
