641	export function isNoiseContent(text: string): boolean {
642	  let matchCount = 0;
643	  for (const pattern of NOISE_PATTERNS) {
644	    if (pattern.test(text)) {
645	      matchCount++;
646	      if (matchCount >= 2) return true;
647	    }
648	  }
649	
650	  const lines = text.split("\n").filter((l) => l.trim().length > 0);
651	  if (lines.length > 3) {
652	    const pathLines = lines.filter((l) => /^\s*(?:\/[\w/.-]+){2,}/.test(l.trim()));
653	    if (pathLines.length / lines.length > 0.5) return true;
654	  }
655	
656	  return false;
657	}
