659	export function shouldAttemptCapture(
660	  exchangeText: string,
661	  minChars = 100,
662	): boolean {
663	  const trimmed = exchangeText.trim();
664	
665	  if (trimmed.length < minChars) return false;
666	
667	  const words = trimmed.toLowerCase().split(/\s+/);
668	  if (words.length <= 3 && words.every((w) => TRIVIAL_RESPONSES.has(w))) {
669	    return false;
670	  }
671	
672	  if (trimmed.includes("<relevant-memories>")) return false;
673	  if (trimmed.startsWith("<") && trimmed.includes("</")) return false;
674	
675	  if (isNoiseContent(trimmed)) return false;
676	
677	  return true;
678	}
