680	export function extractSignificance(
681	  exchangeText: string,
682	): { tags: string[]; type: "memory" | "process" | "task"; summary: string } | null {
683	  const matched: Array<{ tag: string; type: "memory" | "process" | "task" }> = [];
684	
685	  for (const rule of SIGNIFICANCE_RULES) {
686	    if (rule.pattern.test(exchangeText)) {
687	      matched.push({ tag: rule.tag, type: rule.type });
688	    }
689	  }
690	
691	  if (matched.length === 0) return null;
692	
693	  // Require at least 2 different significance tags for rule-based capture
694	  const uniqueTags = new Set(matched.map((m) => m.tag));
695	  if (uniqueTags.size < 2) return null;
696	
697	  const typePriority: Record<string, number> = { task: 3, process: 2, memory: 1 };
698	  const primaryType = matched.reduce(
699	    (best, m) => (typePriority[m.type] > typePriority[best] ? m.type : best),
700	    "memory" as "memory" | "process" | "task",
701	  );
702	
703	  const tags = [...new Set(matched.map((m) => m.tag))];
704	
705	  const sentences = exchangeText
706	    .split(/[.!?\n]+/)
707	    .map((s) => s.trim())
708	    .filter((s) => s.length > 20 && s.length < 500);
709	
710	  const relevantSentences = sentences.filter((s) =>
711	    SIGNIFICANCE_RULES.some((r) => r.pattern.test(s)),
712	  );
713	
714	  const summary = (relevantSentences.length > 0 ? relevantSentences : sentences)
715	    .slice(0, 3)
716	    .join(". ")
717	    .slice(0, 500);
718	
719	  if (!summary) return null;
720	
721	  return { tags, type: primaryType, summary };
722	}
