724	/**
725	 * Strip palaia-injected recall context from message text.
726	 * The recall block is prepended to user messages by before_prompt_build via prependContext.
727	 * OpenClaw merges it into the user message, so agent_end sees it as user content.
728	 * Without stripping, auto-capture re-captures the injected memories -> feedback loop.
729	 *
730	 * The block has a stable structure:
731	 * - Starts with "## Active Memory (palaia)"
732	 * - Contains [t/m], [t/pr], [t/tk] prefixed entries
733	 * - Ends with "[palaia] auto-capture=on..." nudge line
734	 */
735	export function strippalaiaInjectedContext(text: string): string {
736	  // Pattern: "## Active Memory (palaia)" ... "[palaia] auto-capture=on..." + optional trailing newlines
737	  // The nudge line is always present and marks the end of the injected block
738	  const PALAIA_BLOCK_RE = /## Active Memory \(palaia\)[\s\S]*?\[palaia\][^\n]*\n*/;
739	  // Also strip Session Briefing blocks
740	  const BRIEFING_BLOCK_RE = /## Session Briefing \(palaia\)[\s\S]*?(?=\n##|\n\n\n|$)/;
741	  return text
742	    .replace(PALAIA_BLOCK_RE, '')
743	    .replace(BRIEFING_BLOCK_RE, '')
744	    .trim();
745	}
