747	/**
748	 * Strip <private>...</private> blocks from text.
749	 * Content inside private tags is excluded from memory capture.
750	 * Inspired by claude-mem's privacy marker system.
751	 */
752	export function stripPrivateBlocks(text: string): string {
753	  return text.replace(/<private>[\s\S]*?<\/private>/gi, '').trim();
754	}
