43	/**
44	 * Check if an injected entry is relevant to the response text.
45	 * Simple keyword overlap: split title into words, check if >=2 words appear
46	 * in the response (case-insensitive). Words shorter than 3 chars are skipped.
47	 */
48	export function isEntryRelevant(title: string, responseText: string): boolean {
49	  const responseLower = responseText.toLowerCase();
50	  const titleWords = title
51	    .toLowerCase()
52	    .split(/[\s\-_/]+/)
53	    .filter((w) => w.length >= 3);
54	  if (titleWords.length === 0) return false;
55	  const threshold = titleWords.length === 1 ? 1 : 2;
56	  let matches = 0;
57	  for (const word of titleWords) {
58	    if (responseLower.includes(word)) {
59	      matches++;
60	      if (matches >= threshold) return true;
61	    }
62	  }
63	  return false;
64	}
