140	export function extractMessageTexts(messages: unknown[]): Array<{ role: string; text: string; provenance?: string }> {
141	  const result: Array<{ role: string; text: string; provenance?: string }> = [];
142	
143	  for (const msg of messages) {
144	    if (!msg || typeof msg !== "object") continue;
145	    const m = msg as Message;
146	    const role = m.role;
147	    if (!role || typeof role !== "string") continue;
148	
149	    // Extract provenance kind (string or object with .kind)
150	    const rawProvenance = (m as any).provenance?.kind ?? (m as any).provenance;
151	    const provenance = typeof rawProvenance === "string" ? rawProvenance : undefined;
152	
153	    if (typeof m.content === "string" && m.content.trim()) {
154	      result.push({ role, text: m.content.trim(), provenance });
155	      continue;
156	    }
157	
158	    if (Array.isArray(m.content)) {
159	      for (const block of m.content) {
160	        if (
161	          block &&
162	          typeof block === "object" &&
163	          block.type === "text" &&
164	          typeof block.text === "string" &&
165	          block.text.trim()
166	        ) {
167	          result.push({ role, text: block.text.trim(), provenance });
168	        }
169	      }
170	    }
171	  }
172	
173	  return result;
174	}
