176	export function getLastUserMessage(messages: unknown[]): string | null {
177	  const texts = extractMessageTexts(messages);
178	  // Prefer external_user provenance (real human input)
179	  for (let i = texts.length - 1; i >= 0; i--) {
180	    if (texts[i].role === "user" && texts[i].provenance === "external_user")
181	      return texts[i].text;
182	  }
183	  // Fallback: any user message (backward compat for OpenClaw without provenance)
184	  for (let i = texts.length - 1; i >= 0; i--) {
185	    if (texts[i].role === "user") return texts[i].text;
186	  }
187	  return null;
188	}
