331	// ============================================================================
332	// Query-based Recall: Type-weighted reranking (Issue #65)
333	// ============================================================================
334	
335	export interface RankedEntry {
336	  id: string;
337	  body: string;
338	  title: string;
339	  scope: string;
340	  tier: string;
341	  type: string;
342	  score: number;
343	  bm25Score?: number;
344	  embedScore?: number;
345	  weightedScore: number;
346	  created?: string;
347	  tags?: string[];
348	}
349	
350	/**
351	 * Calculate recency boost factor.
352	 * Returns a multiplier: 1.0 (no boost) to 1.0 + boostFactor (max boost for very recent).
353	 * Formula: 1 + boostFactor * exp(-hoursAgo / 24)
354	 */
355	function calcRecencyBoost(created: string | undefined, boostFactor: number): number {
356	  if (!boostFactor || !created) return 1.0;
357	  try {
358	    const hoursAgo = (Date.now() - new Date(created).getTime()) / (1000 * 60 * 60);
359	    if (hoursAgo < 0 || isNaN(hoursAgo)) return 1.0;
360	    return 1.0 + boostFactor * Math.exp(-hoursAgo / 24);
361	  } catch {
362	    return 1.0;
363	  }
364	}
365	
366	export function rerankByTypeWeight(
367	  results: QueryResult["results"],
368	  weights: Record<string, number>,
369	  recencyBoost = 0,
370	  manualEntryBoost = 1.3,
371	): RankedEntry[] {
372	  return results
373	    .map((r) => {
374	      const type = r.type || "memory";
375	      const weight = weights[type] ?? 1.0;
376	      const recency = calcRecencyBoost(r.created, recencyBoost);
377	      // Manual entries (no auto-capture tag) get a boost over auto-captured ones.
378	      // This ensures intentionally stored knowledge ranks higher than conversation noise.
379	      const isAutoCapture = r.tags?.includes("auto-capture") ?? false;
380	      const sourceBoost = isAutoCapture ? 1.0 : manualEntryBoost;
381	      return {
382	        id: r.id,
383	        body: r.content || r.body || "",
384	        title: r.title || "(untitled)",
385	        scope: r.scope,
386	        tier: r.tier,
387	        type,
388	        score: r.score,
389	        bm25Score: r.bm25_score,
390	        embedScore: r.embed_score,
391	        weightedScore: r.score * weight * recency * sourceBoost,
392	        created: r.created,
393	        tags: r.tags,
394	      };
395	    })
396	    .sort((a, b) => b.weightedScore - a.weightedScore);
397	}
398	
399	// ── Context Formatting ──────────────────────────────────────────────────
400	
401	const SCOPE_SHORT: Record<string, string> = { team: "t", private: "p", public: "pub" };
402	const TYPE_SHORT: Record<string, string> = { memory: "m", process: "pr", task: "tk" };
403	
404	/**
405	 * Format a ranked entry as an injectable context line.
406	 *
407	 * In compact mode (progressive disclosure), only title + first line + ID are shown.
408	 * The agent can use `memory_get <id>` for the full entry.
409	 */
410	export function formatEntryLine(entry: RankedEntry, compact: boolean): string {
411	  const scopeKey = SCOPE_SHORT[entry.scope] || entry.scope;
412	  const typeKey = TYPE_SHORT[entry.type] || entry.type;
413	  const prefix = `[${scopeKey}/${typeKey}]`;
414	
415	  if (compact) {
416	    // Compact: title + first line of body + ID reference
417	    const firstLine = entry.body.split("\n")[0]?.slice(0, 120) || "";
418	    const titlePart = entry.body.toLowerCase().startsWith(entry.title.toLowerCase())
419	      ? firstLine
420	      : `${entry.title} — ${firstLine}`;
421	    return `${prefix} ${titlePart} [id:${entry.id}]\n`;
422	  }
423	
424	  // Full: title + complete body
425	  if (entry.body.toLowerCase().startsWith(entry.title.toLowerCase())) {
426	    return `${prefix} ${entry.body}\n\n`;
427	  }
428	  return `${prefix} ${entry.title}\n${entry.body}\n\n`;
429	}
430	
431	/**
432	 * Determine if compact mode should be used based on result count.
433	 * Above threshold, use compact mode to fit more entries in budget.
434	 */
435	export function shouldUseCompactMode(totalResults: number, threshold = 100): boolean {
436	  return totalResults > threshold;
437	}
