1	/**
2	 * palaia CLI subprocess runner.
3	 *
4	 * Executes palaia CLI commands, parses JSON output, handles binary detection
5	 * and timeouts. This is the bridge between the OpenClaw plugin and the
6	 * palaia Python CLI.
7	 */
8	
9	import { execFile } from "node:child_process";
10	import { access, constants } from "node:fs/promises";
11	import { homedir } from "node:os";
12	import { join } from "node:path";
13	
14	export interface RunnerOpts {
15	  /** Working directory for palaia (sets PALAIA_ROOT context) */
16	  workspace?: string;
17	  /** Timeout in milliseconds */
18	  timeoutMs?: number;
19	  /** Override binary path */
20	  binaryPath?: string;
21	}
22	
23	export interface RunResult {
24	  stdout: string;
25	  stderr: string;
26	  exitCode: number;
27	}
28	
29	/** Cached binary path after first detection */
30	let cachedBinary: string | null = null;
31	
32	/**
33	 * Detect the palaia binary location.
34	 *
35	 * Search order:
36	 * 1. Explicit binaryPath from config
37	 * 2. `palaia` in PATH
38	 * 3. `~/.local/bin/palaia` (pipx default)
39	 * 4. `python3 -m palaia` as fallback
40	 * 5. Error with clear message
41	 */
42	export async function detectBinary(
43	  explicitPath?: string
44	): Promise<string> {
45	  if (explicitPath) {
46	    try {
47	      await access(explicitPath, constants.X_OK);
48	      return explicitPath;
49	    } catch {
50	      throw new Error(
51	        `Configured palaia binary not found or not executable: ${explicitPath}`
52	      );
53	    }
54	  }
55	
56	  if (cachedBinary) return cachedBinary;
57	
58	  // Try `palaia` in PATH
59	  try {
60	    const result = await execCommand("palaia", ["--version"], {
61	      timeoutMs: 5000,
62	    });
63	    if (result.exitCode === 0) {
64	      cachedBinary = "palaia";
65	      return "palaia";
66	    }
67	  } catch {
68	    // Not in PATH
69	  }
70	
71	  // Try ~/.local/bin/palaia (pipx default)
72	  const pipxPath = join(homedir(), ".local", "bin", "palaia");
73	  try {
74	    await access(pipxPath, constants.X_OK);
75	    cachedBinary = pipxPath;
76	    return pipxPath;
77	  } catch {
78	    // Not installed via pipx
79	  }
80	
81	  // Try python3 -m palaia
82	  try {
83	    const result = await execCommand("python3", ["-m", "palaia", "--version"], {
84	      timeoutMs: 5000,
85	    });
86	    if (result.exitCode === 0) {
87	      cachedBinary = "python3";
88	      return "python3"; // Will need `-m palaia` prefix
89	    }
90	  } catch {
91	    // Not available
92	  }
93	
94	  throw new Error(
95	    "palaia binary not found. Install with: pip install palaia\n" +
96	      "Or set binaryPath in plugin config."
97	  );
98	}
99	
100	/**
101	 * Check if the detected binary requires `python3 -m palaia` invocation.
102	 */
103	function isPythonModule(binary: string): boolean {
104	  return binary === "python3" || binary.endsWith("/python3");
105	}
106	
107	/**
108	 * Execute a raw command and return result.
109	 */
110	function execCommand(
111	  cmd: string,
112	  args: string[],
113	  opts: { timeoutMs?: number; cwd?: string } = {}
114	): Promise<RunResult> {
115	  return new Promise((resolve, reject) => {
116	    const timeout = opts.timeoutMs || 10000;
117	    const child = execFile(
118	      cmd,
119	      args,
120	      {
121	        timeout,
122	        maxBuffer: 1024 * 1024, // 1MB
123	        cwd: opts.cwd,
124	        env: {
125	          ...process.env,
126	          ...(opts.cwd ? { PALAIA_HOME: opts.cwd } : {}),
127	        },
128	      },
129	      (error, stdout, stderr) => {
130	        if (error && (error as any).killed) {
131	          reject(
132	            new Error(`palaia command timed out after ${timeout}ms: ${cmd} ${args.join(" ")}`)
133	          );
134	          return;
135	        }
136	        resolve({
137	          stdout: stdout?.toString() || "",
138	          stderr: stderr?.toString() || "",
139	          exitCode: error ? (error as any).code || 1 : 0,
140	        });
141	      }
142	    );
143	  });
144	}
145	
146	/**
147	 * Run a palaia CLI command and return raw output.
148	 */
149	export async function run(
150	  args: string[],
151	  opts: RunnerOpts = {}
152	): Promise<string> {
153	  const binary = await detectBinary(opts.binaryPath);
154	  const timeoutMs = opts.timeoutMs || 3000;
155	
156	  let cmd: string;
157	  let cmdArgs: string[];
158	
159	  if (isPythonModule(binary)) {
160	    cmd = binary;
161	    cmdArgs = ["-m", "palaia", ...args];
162	  } else {
163	    cmd = binary;
164	    cmdArgs = [...args];
165	  }
166	
167	  let result = await execCommand(cmd, cmdArgs, {
168	    timeoutMs,
169	    cwd: opts.workspace,
170	  });
171	
172	  // Retry once on lock/timeout errors (L-5: concurrent CLI write safety)
173	  if (result.exitCode !== 0) {
174	    const errMsg = result.stderr.trim() || result.stdout.trim();
175	    const errLower = errMsg.toLowerCase();
176	    if (errLower.includes("lock") || errLower.includes("timeout")) {
177	      await new Promise((r) => setTimeout(r, 500));
178	      result = await execCommand(cmd, cmdArgs, {
179	        timeoutMs,
180	        cwd: opts.workspace,
181	      });
182	    }
183	  }
184	
185	  if (result.exitCode !== 0) {
186	    const errMsg = result.stderr.trim() || result.stdout.trim();
187	    throw new Error(`palaia CLI error (exit ${result.exitCode}): ${errMsg}`);
188	  }
189	
190	  return result.stdout;
191	}
192	
193	/**
194	 * Run a palaia CLI command and parse JSON output.
195	 */
196	export async function runJson<T = unknown>(
197	  args: string[],
198	  opts: RunnerOpts = {}
199	): Promise<T> {
200	  const stdout = await run([...args, "--json"], opts);
201	  try {
202	    return JSON.parse(stdout) as T;
203	  } catch {
204	    throw new Error(
205	      `Failed to parse palaia JSON output: ${stdout.slice(0, 200)}`
206	    );
207	  }
208	}
209	
210	/**
211	 * Run WAL recovery on startup.
212	 */
213	export async function recover(opts: RunnerOpts = {}): Promise<{
214	  replayed: number;
215	  errors: number;
216	}> {
217	  try {
218	    return await runJson<{ replayed: number; errors: number }>(
219	      ["recover"],
220	      { ...opts, timeoutMs: opts.timeoutMs || 10000 }
221	    );
222	  } catch (error) {
223	    // Recovery failure is non-fatal — log and continue
224	    console.warn(`[palaia] WAL recovery warning: ${error}`);
225	    return { replayed: 0, errors: 1 };
226	  }
227	}
228	
229	/**
230	 * Reset cached binary (for testing).
231	 */
232	export function resetCache(): void {
233	  cachedBinary = null;
234	}
