236	// ============================================================================
237	// EmbedServerManager (v2.0.8)
238	// ============================================================================
239	
240	import { spawn, type ChildProcess } from "node:child_process";
241	import { createInterface, type Interface as ReadlineInterface } from "node:readline";
242	
243	export interface EmbedServerQueryParams {
244	  text: string;
245	  top_k?: number;
246	  agent?: string;
247	  project?: string;
248	  scope?: string;
249	  type?: string;
250	  status?: string;
251	  priority?: string;
252	  assignee?: string;
253	  instance?: string;
254	  include_cold?: boolean;
255	  cross_project?: boolean;
256	}
257	
258	interface PendingRequest {
259	  resolve: (value: any) => void;
260	  reject: (reason: any) => void;
261	  timer: ReturnType<typeof setTimeout>;
262	}
263	
264	/**
265	 * Manages a long-lived `palaia embed-server` subprocess.
266	 *
267	 * The subprocess loads the embedding model once and serves queries over
268	 * stdin/stdout JSON-RPC, reducing query time from ~14s to ~0.5s.
269	 *
270	 * Features:
271	 * - Lazy start on first use
272	 * - Auto-restart on crash (max 3 retries)
273	 * - Graceful shutdown on process exit
274	 * - Timeout per request with fallback to CLI
275	 */
276	export class EmbedServerManager {
277	  private proc: ChildProcess | null = null;
278	  private rl: ReadlineInterface | null = null;
279	  private ready = false;
280	  private starting = false;
281	  private restartCount = 0;
282	  private maxRestarts = 3;
283	  private opts: RunnerOpts;
284	  private pendingRequest: PendingRequest | null = null;
285	  private cleanupRegistered = false;
286	
287	  constructor(opts: RunnerOpts = {}) {
288	    this.opts = opts;
289	  }
290	
291	  /**
292	   * Start the embed-server subprocess. Resolves when the server signals ready.
293	   */
294	  async start(): Promise<void> {
295	    if (this.ready || this.starting) return;
296	    this.starting = true;
297	
298	    try {
299	      const binary = await detectBinary(this.opts.binaryPath);
300	      let cmd: string;
301	      let args: string[];
302	
303	      if (isPythonModule(binary)) {
304	        cmd = binary;
305	        args = ["-m", "palaia", "embed-server"];
306	      } else {
307	        cmd = binary;
308	        args = ["embed-server"];
309	      }
310	
311	      this.proc = spawn(cmd, args, {
312	        stdio: ["pipe", "pipe", "pipe"],
313	        cwd: this.opts.workspace,
314	        env: {
315	          ...process.env,
316	          ...(this.opts.workspace ? { PALAIA_HOME: this.opts.workspace } : {}),
317	        },
318	      });
319	
320	      this.rl = createInterface({ input: this.proc.stdout! });
321	
322	      // Wait for the "ready" signal
323	      await new Promise<void>((resolve, reject) => {
324	        const timeout = setTimeout(() => {
325	          reject(new Error("Embed server startup timed out"));
326	        }, 30_000);
327	
328	        const onLine = (line: string) => {
329	          try {
330	            const msg = JSON.parse(line);
331	            if (msg.result === "ready") {
332	              clearTimeout(timeout);
333	              this.ready = true;
334	              this.starting = false;
335	              this.restartCount = 0;
336	              // Set up ongoing line handler
337	              this.rl!.on("line", (l) => this.handleLine(l));
338	              resolve();
339	            }
340	          } catch {
341	            // Ignore non-JSON lines during startup
342	          }
343	        };
344	
345	        this.rl!.once("line", onLine);
346	
347	        this.proc!.on("error", (err) => {
348	          clearTimeout(timeout);
349	          reject(err);
350	        });
351	      });
352	
353	      // Handle crash
354	      this.proc.on("exit", (code) => {
355	        this.ready = false;
356	        this.proc = null;
357	        this.rl = null;
358	        // Reject any pending request
359	        if (this.pendingRequest) {
360	          this.pendingRequest.reject(new Error(`Embed server exited with code ${code}`));
361	          clearTimeout(this.pendingRequest.timer);
362	          this.pendingRequest = null;
363	        }
364	        // Reject all queued requests
365	        for (const queued of this.requestQueue) {
366	          queued.reject(new Error(`Embed server exited with code ${code}`));
367	        }
368	        this.requestQueue = [];
369	      });
370	
371	      // Register cleanup
372	      if (!this.cleanupRegistered) {
373	        this.cleanupRegistered = true;
374	        process.on("exit", () => this.stopSync());
375	      }
376	    } catch (err) {
377	      this.starting = false;
378	      throw err;
379	    }
380	  }
381	
382	  /**
383	   * Send a query to the embed server.
384	   */
385	  async query(params: EmbedServerQueryParams, timeoutMs = 3000): Promise<any> {
386	    await this.ensureRunning();
387	    return this.sendRequest({ method: "query", params }, timeoutMs);
388	  }
389	
390	  /**
391	   * Trigger warmup (index missing entries).
392	   */
393	  async warmup(timeoutMs = 60_000): Promise<any> {
394	    await this.ensureRunning();
395	    return this.sendRequest({ method: "warmup" }, timeoutMs);
396	  }
397	
398	  /**
399	   * Health check.
400	   */
401	  async ping(timeoutMs = 3000): Promise<boolean> {
402	    try {
403	      await this.ensureRunning();
404	      const resp = await this.sendRequest({ method: "ping" }, timeoutMs);
405	      return resp?.result === "pong";
406	    } catch {
407	      return false;
408	    }
409	  }
410	
411	  /**
412	   * Get server status.
413	   */
414	  async status(timeoutMs = 3000): Promise<any> {
415	    await this.ensureRunning();
416	    return this.sendRequest({ method: "status" }, timeoutMs);
417	  }
418	
419	  /**
420	   * Stop the subprocess gracefully.
421	   */
422	  async stop(): Promise<void> {
423	    if (!this.proc) return;
424	    try {
425	      await this.sendRequest({ method: "shutdown" }, 3000);
426	    } catch {
427	      // Force kill if shutdown request fails
428	    }
429	    this.stopSync();
430	  }
431	
432	  /**
433	   * Synchronous stop (for process.on('exit')).
434	   */
435	  private stopSync(): void {
436	    if (this.proc) {
437	      try {
438	        this.proc.kill("SIGTERM");
439	      } catch {
440	        // Already dead
441	      }
442	      this.proc = null;
443	      this.rl = null;
444	      this.ready = false;
445	    }
446	  }
447	
448	  /**
449	   * Whether the server is currently running and ready.
450	   */
451	  get isRunning(): boolean {
452	    return this.ready && this.proc !== null;
453	  }
454	
455	  private async ensureRunning(): Promise<void> {
456	    if (this.ready && this.proc) return;
457	    if (this.restartCount >= this.maxRestarts) {
458	      throw new Error("Embed server max restarts exceeded");
459	    }
460	    this.restartCount++;
461	    await this.start();
462	  }
463	
464	  /** Maximum number of queued requests before rejecting */
465	  private maxQueueSize = 10;
466	  /** Queue of pending requests waiting to be sent */
467	  private requestQueue: Array<{
468	    request: Record<string, unknown>;
469	    timeoutMs: number;
470	    resolve: (value: any) => void;
471	    reject: (reason: any) => void;
472	  }> = [];
473	
474	  private sendRequest(request: Record<string, unknown>, timeoutMs: number): Promise<any> {
475	    return new Promise((resolve, reject) => {
476	      if (!this.proc?.stdin?.writable) {
477	        reject(new Error("Embed server not running"));
478	        return;
479	      }
480	
481	      // If a request is already in flight, queue this one
482	      if (this.pendingRequest) {
483	        if (this.requestQueue.length >= this.maxQueueSize) {
484	          reject(new Error("Embed server queue full"));
485	          return;
486	        }
487	        this.requestQueue.push({ request, timeoutMs, resolve, reject });
488	        return;
489	      }
490	
491	      this._sendImmediate(request, timeoutMs, resolve, reject);
492	    });
493	  }
494	
495	  private _sendImmediate(
496	    request: Record<string, unknown>,
497	    timeoutMs: number,
498	    resolve: (value: any) => void,
499	    reject: (reason: any) => void,
500	  ): void {
501	    const timer = setTimeout(() => {
502	      this.pendingRequest = null;
503	      reject(new Error(`Embed server request timed out after ${timeoutMs}ms`));
504	      this._drainQueue();
505	    }, timeoutMs);
506	
507	    this.pendingRequest = { resolve, reject, timer };
508	
509	    const line = JSON.stringify(request) + "\n";
510	    this.proc!.stdin!.write(line);
511	  }
512	
513	  private _drainQueue(): void {
514	    if (this.pendingRequest || this.requestQueue.length === 0) return;
515	    const next = this.requestQueue.shift()!;
516	    if (!this.proc?.stdin?.writable) {
517	      next.reject(new Error("Embed server not running"));
518	      return;
519	    }
520	    this._sendImmediate(next.request, next.timeoutMs, next.resolve, next.reject);
521	  }
522	
523	  private handleLine(line: string): void {
524	    if (!this.pendingRequest) return;
525	    try {
526	      const msg = JSON.parse(line);
527	      const pending = this.pendingRequest;
528	      this.pendingRequest = null;
529	      clearTimeout(pending.timer);
530	      if (msg.error) {
531	        pending.reject(new Error(msg.error));
532	      } else {
533	        pending.resolve(msg);
534	      }
535	      // Process next queued request
536	      this._drainQueue();
537	    } catch {
538	      // Ignore non-JSON lines
539	    }
540	  }
541	}
