2	 * Plugin configuration schema and defaults for @byte5ai/palaia.
3	 */
4	
5	export interface RecallTypeWeights {
6	  process: number;
7	  task: number;
8	  memory: number;
9	  [key: string]: number;
10	}
11	
12	export interface PalaiaPluginConfig {
13	  /** Path to palaia binary (default: auto-detect) */
14	  binaryPath?: string;
15	  /** palaia workspace path (default: agent workspace) */
16	  workspace?: string;
17	  /** Default tier filter: "hot" | "warm" | "all" */
18	  tier: string;
19	  /** Default max results for queries */
20	  maxResults: number;
21	  /** Timeout for CLI calls in milliseconds */
22	  timeoutMs: number;
23	  /** Inject HOT memory into agent context on prompt build */
24	  memoryInject: boolean;
25	  /** Max characters for injected memory context */
26	  maxInjectedChars: number;
27	
28	  // ── Auto-Capture (Issue #64) ─────────────────────────────────
29	  /** Enable automatic memory capture after agent exchanges */
30	  autoCapture: boolean;
31	  /** How often to capture: "every" | "significant" (default: "significant") */
32	  captureFrequency: "every" | "significant";
33	  /** Minimum exchange turns before capture is attempted */
34	  captureMinTurns: number;
35	  /** Model override for LLM-based extraction (e.g. "anthropic/claude-haiku-3", or "cheap") */
36	  captureModel?: string;
37	  /** Minimum significance score for LLM-extracted items (0.0-1.0, default: 0.3) */
38	  captureMinSignificance: number;
39	
40	  // ── Metadata Overrides (Issue #81) ─────────────────────────
41	  /** Static scope override for auto-capture (default: undefined → LLM detection) */
42	  captureScope?: string;
43	  /** Static project override for auto-capture (default: undefined → LLM detection) */
44	  captureProject?: string;
45	
46	  // ── Transparency Features (Issue #87) ────────────────────────
47	  /** Show memory source footnotes in agent responses (default: true) */
48	  showMemorySources: boolean;
49	  /** Show capture confirmation in agent responses (default: true) */
50	  showCaptureConfirm: boolean;
51	
52	  // ── Query-based Recall (Issue #65) ───────────────────────────
53	  /** Recall mode: "list" (context-independent) or "query" (context-relevant) */
54	  recallMode: "list" | "query";
55	  /** Type-aware weighting for recall results */
56	  recallTypeWeight: RecallTypeWeights;
57	
58	  // ── Recall Quality (Issue #65) ───────────────────────────────
59	  /** Minimum score for a recall result to be considered relevant (default: 0.7) */
60	  recallMinScore: number;
61	
62	  // ── Embedding Server (v2.0.8) ──────────────────────────────
63	  /** Enable long-lived embedding server subprocess for fast queries (default: true) */
64	  embeddingServer: boolean;
65	
66	  // ── Session Continuity (v3.0) ─────────────────────────────
67	  /** Enable automatic session summaries on session end/reset (default: true) */
68	  sessionSummary: boolean;
69	  /** Enable session briefing injection on session start (default: true) */
70	  sessionBriefing: boolean;
71	  /** Max characters for session briefing (default: 1500) */
72	  sessionBriefingMaxChars: number;
73	  /** Enable tool observation tracking via after_tool_call hook (default: true) */
74	  captureToolObservations: boolean;
75	  /** Recency boost factor for recall (0 = off, 0.3 = 30% boost for <24h entries) */
76	  recallRecencyBoost: number;
77	  /** Boost factor for manually written entries vs auto-captured (default: 1.3 = 30% boost) */
78	  manualEntryBoost: number;
79	}
