111	/**
112	 * Merge user config with defaults. Unknown keys are ignored.
113	 */
114	export function resolveConfig(
115	  userConfig: Partial<PalaiaPluginConfig> | undefined
116	): PalaiaPluginConfig {
117	  const base = { ...DEFAULT_CONFIG, ...userConfig };
118	  // Deep-merge recallTypeWeight
119	  if (userConfig?.recallTypeWeight) {
120	    base.recallTypeWeight = {
121	      ...DEFAULT_RECALL_TYPE_WEIGHTS,
122	      ...userConfig.recallTypeWeight,
