13	import type { OpenClawPluginApi } from "../types.js";
14	import type { PalaiaPluginConfig } from "../config.js";
15	import { run, type RunnerOpts } from "../runner.js";
16	import {
17	  getOrCreateSessionState,
18	  deleteSessionState,
19	  type PendingBriefing,
20	  type ToolObservation,
21	} from "./state.js";
22	import {
23	  strippalaiaInjectedContext,
24	  stripPrivateBlocks,
25	  trimToRecentExchanges,
26	  extractWithLLM,
27	} from "./capture.js";
