31	/**
32	 * Resolve effective capture scope from priorities (per-agent override)
33	 * falling back to plugin config, then to "team".
34	 */
35	async function getEffectiveCaptureScope(config: PalaiaPluginConfig): Promise<string> {
36	  try {
37	    const prio = await loadPriorities(config.workspace || "");
38	    const agentId = process.env.PALAIA_AGENT || undefined;
39	    const resolved = resolvePriorities(prio, {
40	      recallTypeWeight: config.recallTypeWeight,
41	      recallMinScore: config.recallMinScore,
42	      maxInjectedChars: config.maxInjectedChars,
43	      tier: config.tier,
44	    }, agentId);
45	    if (resolved.captureScope) return resolved.captureScope;
46	  } catch {
47	    // Fall through to config default
48	  }
49	  return config.captureScope || "team";
50	}
