60	// ── Session Briefing ────────────────────────────────────────���───────────
61	
62	/**
63	 * Load session briefing data (last session summary + open tasks).
64	 * Called during session_start to prepare context for the first turn.
65	 */
66	export async function loadSessionBriefing(
67	  config: PalaiaPluginConfig,
68	  logger: { info(...a: unknown[]): void; warn(...a: unknown[]): void },
69	): Promise<PendingBriefing> {
70	  const opts = buildRunnerOpts(config);
71	  let summary: string | null = null;
72	  let summaryCreated: number = Date.now();
73	  const openTasks: string[] = [];
74	
75	  // Load last session summary and open tasks in parallel
76	  const { runJson } = await import("../runner.js");
77	  const [summaryResult, tasksResult] = await Promise.allSettled([
78	    runJson<{ results: Array<{ title: string; body: string; created?: string }> }>(
79	      ["query", "session-summary", "--limit", "1", "--tags", "session-summary"],
80	      { ...opts, timeoutMs: 5000 },
81	    ),
82	    runJson<{ results: Array<{ title: string; body: string; priority?: string }> }>(
83	      ["list", "--type", "task", "--status", "open", "--limit", "5"],
84	      { ...opts, timeoutMs: 5000 },
85	    ),
86	  ]);
87	
88	  if (summaryResult.status === "fulfilled" && summaryResult.value?.results?.[0]) {
89	    summary = summaryResult.value.results[0].body;
90	    const created = summaryResult.value.results[0].created;
91	    if (created) {
92	      const parsed = new Date(created).getTime();
93	      if (!isNaN(parsed)) summaryCreated = parsed;
94	    }
95	  }
96	
97	  if (tasksResult.status === "fulfilled" && tasksResult.value?.results) {
98	    for (const task of tasksResult.value.results) {
99	      const prio = task.priority ? ` (${task.priority})` : "";
100	      openTasks.push(`${task.title}${prio}`);
101	    }
102	  }
103	
104	  return { summary, openTasks, timestamp: summaryCreated };
105	}
