107	/**
108	 * Format a pending briefing into injectable text.
109	 */
110	export function formatBriefing(briefing: PendingBriefing, maxChars: number): string {
111	  if (maxChars <= 0) return "";
112	  if (!briefing.summary && briefing.openTasks.length === 0) return "";
113	
114	  const parts: string[] = ["## Session Briefing (palaia)\n"];
115	
116	  if (briefing.summary) {
117	    const agoMs = Date.now() - briefing.timestamp;
118	    const agoMin = Math.round(agoMs / 60_000);
119	    const agoStr = agoMin < 1 ? "just now" :
120	      agoMin < 60 ? `${agoMin}m ago` :
121	      `${Math.round(agoMin / 60)}h ago`;
122	    parts.push(`Last session (${agoStr}):`);
123	    parts.push(briefing.summary);
124	    parts.push("");
125	  }
126	
127	  if (briefing.openTasks.length > 0) {
128	    parts.push("Open tasks:");
129	    for (const task of briefing.openTasks) {
130	      parts.push(`- ${task}`);
131	    }
132	    parts.push("");
133	  }
134	
135	  const text = parts.join("\n");
136	  return text.length <= maxChars ? text : text.slice(0, maxChars - 3) + "...";
137	}
