139	// ── Session Summary Capture ─────────────────────────────────────────────
140	
141	/**
142	 * Extract and save a session summary from conversation messages.
143	 * Called during before_reset (with messages) or session_end (without).
144	 */
145	export async function captureSessionSummary(
146	  messages: unknown[] | undefined,
147	  sessionKey: string,
148	  api: OpenClawPluginApi,
149	  config: PalaiaPluginConfig,
150	  logger: { info(...a: unknown[]): void; warn(...a: unknown[]): void },
151	): Promise<void> {
152	  const opts = buildRunnerOpts(config);
153	  const state = getOrCreateSessionState(sessionKey);
154	
155	  // Guard: prevent double-save (before_reset + session_end race)
156	  if (state.summarySaved) return;
157	  let summaryText: string | null = null;
158	
159	  if (messages && messages.length > 0) {
160	    // Try LLM-based summary extraction
161	    try {
162	      const results = await extractWithLLM(messages, api.config, {
163	        captureModel: config.captureModel,
164	        workspace: config.workspace,
165	      }, []);
166	
167	      if (results.length > 0) {
168	        summaryText = results[0].content;
169	      }
170	    } catch {
171	      // Fall through to rule-based
172	    }
173	
174	    // Rule-based fallback: last 3 user+assistant pairs
175	    if (!summaryText) {
176	      const allTexts = extractMessageTexts(messages);
177	      const cleaned = allTexts.map((t: { role: string; text: string }) => ({
178	        ...t,
179	        text: stripPrivateBlocks(
180	          t.role === "user" ? strippalaiaInjectedContext(t.text) : t.text
181	        ),
182	      }));
183	      const recent = trimToRecentExchanges(cleaned, 3);
184	      if (recent.length > 0) {
185	        summaryText = recent
186	          .map(t => `[${t.role}]: ${t.text.slice(0, 200)}`)
187	          .join("\n")
188	          .slice(0, 500);
189	      }
190	    }
191	  } else {
192	    // No messages available (session_end without before_reset).
193	    // Use accumulated tool observations as summary.
194	    if (state.toolObservations.length > 0) {
195	      summaryText = state.toolObservations
196	        .map(o => `${o.toolName}: ${o.resultSummary}`)
197	        .join("\n")
198	        .slice(0, 500);
199	    }
200	  }
201	
202	  if (!summaryText) return;
203	
204	  // Save session summary
205	  try {
206	    const scope = await getEffectiveCaptureScope(config);
207	    const args: string[] = [
208	      "write", summaryText,
209	      "--type", "memory",
210	      "--tags", "session-summary,auto-capture",
211	      "--scope", scope,
212	    ];
213	    if (state.autoSessionId) args.push("--instance", state.autoSessionId);
214	    const agentName = process.env.PALAIA_AGENT || undefined;
215	    if (agentName) args.push("--agent", agentName);
216	
217	    await run(args, { ...opts, timeoutMs: 10_000 });
218	    state.summarySaved = true;  // Only mark after successful write
219	    logger.info(`[palaia] Session summary saved (${summaryText.length} chars)`);
220	  } catch (error) {
221	    // Don't set summarySaved — allow retry from session_end if before_reset failed
222	    logger.warn(`[palaia] Failed to save session summary: ${error}`);
223	  }
224	}
225	
226	// ── Tool Observations ─────────────────────────────────────────────────���─
227	
228	/** Tools worth tracking for observations. */
229	const TRACKED_TOOLS = new Set([
230	  // File operations
231	  "memory_search", "memory_get", "memory_write",
232	  "read_file", "write_file", "edit_file",
233	  "search_files", "list_files",
234	  // Shell
235	  "bash", "shell", "terminal",
236	  // Web
237	  "web_search", "fetch_url",
238	]);
239	
240	/**
241	 * Process an after_tool_call event into a tool observation.
242	 * Returns null if the tool isn't worth tracking.
243	 */
244	export function processToolCall(
245	  toolName: string,
246	  params: Record<string, unknown>,
247	  result: unknown,
248	  durationMs: number,
249	): ToolObservation | null {
250	  // Only track relevant tools (skip internal/framework tools)
251	  if (!TRACKED_TOOLS.has(toolName) && !toolName.startsWith("palaia_")) {
252	    return null;
253	  }
254	
255	  // Skip errored tool calls (only null/undefined, not falsy 0/"")
256	  if (result === undefined || result === null) return null;
257	
258	  // Summarize params (keep it short)
259	  const paramKeys = Object.keys(params).slice(0, 3);
260	  const paramsSummary = paramKeys
261	    .map(k => {
262	      const v = params[k];
263	      try {
264	        const s = typeof v === "string" ? v.slice(0, 80) : JSON.stringify(v)?.slice(0, 80) ?? "";
265	        return `${k}=${s}`;
266	      } catch {
267	        return `${k}=[object]`;
268	      }
269	    })
270	    .join(", ");
271	
272	  // Summarize result
273	  let resultSummary: string;
274	  if (typeof result === "string") {
275	    resultSummary = result.slice(0, 200);
276	  } else if (typeof result === "object" && result !== null) {
277	    resultSummary = JSON.stringify(result).slice(0, 200);
278	  } else {
279	    resultSummary = String(result).slice(0, 200);
280	  }
281	
282	  return {
283	    toolName,
284	    paramsSummary,
285	    resultSummary,
286	    durationMs,
287	    timestamp: Date.now(),
288	  };
289	}
290	
291	// ── Hook Registration ───────────────────────────────────────────────────
292	
293	/**
294	 * Register all session lifecycle hooks.
295	 * Called from hooks/index.ts during plugin registration.
296	 */
297	export function registerSessionHooks(
298	  api: OpenClawPluginApi,
299	  config: PalaiaPluginConfig,
300	): void {
301	  const logger = api.logger;
302	
303	  // ── session_start: Load briefing for context restoration ──────────
304	  if (config.sessionBriefing) {
305	    api.on("session_start", async (event: any, ctx: any) => {
306	      const sessionKey = ctx?.sessionKey || ctx?.sessionId;
307	      if (!sessionKey) return;
308	      const state = getOrCreateSessionState(sessionKey);
309	
310	      // Create a promise that before_prompt_build can await
311	      let resolve: () => void;
312	      state.briefingReady = new Promise<void>(r => { resolve = r; });
313	      state.briefingReadyResolve = resolve!;
314	
315	      try {
316	        state.pendingBriefing = await loadSessionBriefing(config, logger);
317	        if (state.pendingBriefing.summary || state.pendingBriefing.openTasks.length > 0) {
318	          logger.info(`[palaia] Session briefing loaded for ${sessionKey}`);
319	        }
320	      } catch (error) {
321	        logger.warn(`[palaia] Failed to load session briefing: ${error}`);
322	      } finally {
323	        state.briefingReadyResolve?.();
324	      }
325	    });
326	  }
327	
328	  // ── session_end: Save session summary ─────────────────────────────
329	  if (config.sessionSummary) {
330	    api.on("session_end", async (event: any, ctx: any) => {
331	      const sessionKey = ctx?.sessionKey || ctx?.sessionId;
332	      if (!sessionKey) return;
333	
334	      try {
335	        // Only save summary if session had meaningful interaction.
336	        // Guard: if OpenClaw omits messageCount, fall back to tool observations
337	        // as evidence of interaction rather than silently skipping.
338	        const messageCount = (event as any)?.messageCount;
339	        const state = getOrCreateSessionState(sessionKey);
340	        const hasInteraction = (typeof messageCount === "number" && messageCount >= 4)
341	          || (messageCount === undefined && state.toolObservations.length > 0);
342	        if (hasInteraction) {
343	          await captureSessionSummary(undefined, sessionKey, api, config, logger);
344	        }
345	      } catch (error) {
346	        logger.warn(`[palaia] session_end summary failed: ${error}`);
347	      } finally {
348	        deleteSessionState(sessionKey);
349	      }
350	    });
351	  }
352	
353	  // ── before_reset: Save session summary with messages (priority) ───
354	  if (config.sessionSummary) {
355	    api.on("before_reset", async (event: any, ctx: any) => {
356	      const sessionKey = ctx?.sessionKey || ctx?.sessionId;
357	      if (!sessionKey) return;
358	
359	      try {
360	        const messages = (event as any)?.messages;
361	        if (messages && Array.isArray(messages) && messages.length >= 4) {
362	          await captureSessionSummary(messages, sessionKey, api, config, logger);
363	        }
364	      } catch (error) {
365	        logger.warn(`[palaia] before_reset summary failed: ${error}`);
366	      }
367	    });
368	  }
369	
370	  // ── llm_input: Model switch detection ─────────────────────────────
371	  api.on("llm_input", (event: any, ctx: any) => {
372	    const sessionKey = ctx?.sessionKey || ctx?.sessionId;
373	    if (!sessionKey) return;
374	    const state = getOrCreateSessionState(sessionKey);
375	
376	    const model = (event as any)?.model;
377	    if (!model) return;
378	
379	    if (state.lastModel && model !== state.lastModel) {
380	      state.modelSwitchDetected = true;
381	      logger.info(`[palaia] Model switch detected: ${state.lastModel} → ${model}`);
382	
383	      // Re-load briefing for next assemble
384	      if (config.sessionBriefing && !state.pendingBriefing) {
385	        loadSessionBriefing(config, logger).then(briefing => {
386	          state.pendingBriefing = briefing;
387	          state.briefingDelivered = false;
388	        }).catch(() => {});
389	      }
390	    }
391	    state.lastModel = model;
392	  });
393	
394	  // ── after_tool_call: Tool observation tracking ────────────────��───
395	  if (config.captureToolObservations) {
396	    api.on("after_tool_call", (event: any, ctx: any) => {
397	      const sessionKey = ctx?.sessionKey || ctx?.sessionId;
398	      if (!sessionKey) return;
399	      const state = getOrCreateSessionState(sessionKey);
400	
401	      const obs = processToolCall(
402	        (event as any)?.toolName || "",
403	        (event as any)?.params || {},
404	        (event as any)?.result,
405	        (event as any)?.durationMs || 0,
406	      );
407	
408	      if (obs) {
409	        state.toolObservations.push(obs);
410	        // Keep max 50 observations per session to prevent memory bloat
411	        if (state.toolObservations.length > 50) {
412	          state.toolObservations.shift();
413	        }
414	      }
415	    });
416	  }
417	
418	  // ── subagent_spawning: Log sub-agent spawn for context tracking ─
419	  api.on("subagent_spawning", async (event: any, _ctx: any) => {
420	    try {
421	      const childKey = (event as any)?.childSessionKey;
422	      if (!childKey) return;
423	      logger.info(`[palaia] Sub-agent spawning: ${childKey}`);
424	    } catch {
425	      // Non-fatal
426	    }
427	  });
428	
429	  // ── subagent_ended: Capture sub-agent results ─────────────────
430	  if (config.autoCapture) {
431	    api.on("subagent_ended", async (event: any, _ctx: any) => {
432	      try {
433	        const outcome = (event as any)?.outcome;
434	        if (outcome !== "ok") return;
435	
436	        const childKey = (event as any)?.targetSessionKey;
437	        if (!childKey || !api.runtime?.subagent?.getSessionMessages) return;
438	
439	        const result = await api.runtime.subagent.getSessionMessages({
440	          sessionKey: childKey,
441	          limit: 10,
442	        });
443	        if (!result?.messages?.length) return;
444	
445	        const texts = extractMessageTexts(result.messages);
446	        const summaryParts = texts.slice(-4).map(
447	          (t: { role: string; text: string }) => `[${t.role}]: ${t.text.slice(0, 200)}`
448	        );
449	        if (summaryParts.length === 0) return;
450	
451	        const summaryText = `Sub-agent result:\n${summaryParts.join("\n")}`.slice(0, 500);
452	        const subagentScope = await getEffectiveCaptureScope(config);
453	        await run([
454	          "write", summaryText,
455	          "--type", "memory",
456	          "--tags", "subagent-result,auto-capture",
457	          "--scope", subagentScope,
458	        ], { ...buildRunnerOpts(config), timeoutMs: 10_000 });
459	        logger.info(`[palaia] Sub-agent result captured (${summaryText.length} chars)`);
460	      } catch (error) {
461	        logger.warn(`[palaia] Sub-agent result capture failed: ${error}`);
462	      }
463	    });
464	  }
465	}
