1	/**
2	 * Injection priority management for multi-agent setups (Issue #121).
3	 *
4	 * TypeScript-side integration: loads `.palaia/priorities.json`,
5	 * resolves layered config (global -> agent -> project), and provides
6	 * blocking/filtering utilities for recall injection.
7	 *
8	 * Mirrors the Python implementation in palaia/priorities.py.
9	 */
10	
11	import { readFile } from "node:fs/promises";
12	import { join } from "node:path";
13	
14	// ============================================================================
15	// Interfaces
16	// ============================================================================
17	
18	export interface PrioritiesConfig {
19	  version: number;
20	  blocked: string[];
21	  recallTypeWeight?: Record<string, number>;
22	  recallMinScore?: number;
23	  maxInjectedChars?: number;
24	  tier?: string;
25	  agents?: Record<string, AgentPriorityOverride>;
26	  projects?: Record<string, ProjectPriorityOverride>;
27	}
28	
29	export interface AgentPriorityOverride {
30	  blocked?: string[];
31	  recallTypeWeight?: Record<string, number>;
32	  recallMinScore?: number;
33	  maxInjectedChars?: number;
34	  tier?: string;
35	  scopeVisibility?: string[];  // Issue #145: agent isolation
36	  captureScope?: string;       // Issue #147: per-agent write scope
37	}
38	
39	export interface ProjectPriorityOverride {
40	  blocked?: string[];
41	  recallTypeWeight?: Record<string, number>;
42	}
43	
44	export interface ResolvedPriorities {
45	  blocked: Set<string>;
46	  recallTypeWeight: Record<string, number>;
47	  recallMinScore: number;
48	  maxInjectedChars: number;
49	  tier: string;
50	  scopeVisibility: string[] | null;  // Issue #145: agent isolation
51	  captureScope: string | null;       // Issue #147: per-agent write scope
52	}
53	
54	// ============================================================================
55	// Defaults (match Python side)
56	// ============================================================================
57	
58	const DEFAULT_TYPE_WEIGHTS: Record<string, number> = { process: 1.5, task: 1.2, memory: 1.0 };
59	const DEFAULT_MIN_SCORE = 0.0;
60	const DEFAULT_MAX_CHARS = 4000;
61	const DEFAULT_TIER = "hot";
62	
63	// ============================================================================
64	// TTL Cache
65	// ============================================================================
66	
67	const CACHE_TTL_MS = 30_000;
68	
69	let _cache: {
70	  workspace: string;
71	  data: PrioritiesConfig | null;
72	  loadedAt: number;
73	} | null = null;
74	
75	/** Reset cache (for testing). */
76	export function resetPrioritiesCache(): void {
77	  _cache = null;
78	}
79	
80	// ============================================================================
81	// Load
82	// ============================================================================
83	
84	/**
85	 * Load `.palaia/priorities.json` from the given workspace directory.
86	 * Returns null if the file does not exist or is invalid.
87	 * Results are cached with a 30-second TTL.
88	 */
89	export async function loadPriorities(workspace: string): Promise<PrioritiesConfig | null> {
90	  const now = Date.now();
91	  if (_cache && _cache.workspace === workspace && (now - _cache.loadedAt) < CACHE_TTL_MS) {
92	    return _cache.data;
93	  }
94	
95	  const path = join(workspace, ".palaia", "priorities.json");
96	  let data: PrioritiesConfig | null = null;
97	
98	  try {
99	    const raw = await readFile(path, "utf-8");
100	    const parsed = JSON.parse(raw);
101	    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
102	      data = parsed as PrioritiesConfig;
103	    }
104	  } catch {
105	    // File doesn't exist or is invalid — return null
106	  }
107	
108	  _cache = { workspace, data, loadedAt: now };
109	  return data;
110	}
111	
112	// ============================================================================
113	// Resolve
114	// ============================================================================
115	
116	export interface PriorityDefaults {
117	  recallTypeWeight: Record<string, number>;
118	  recallMinScore: number;
119	  maxInjectedChars: number;
120	  tier: string;
121	}
122	
123	/**
124	 * Merge priority layers into a flat resolved config.
125	 *
126	 * Resolution order: plugin defaults -> global overrides -> agent overrides -> project overrides.
127	 * `blocked` is a union across all layers.
128	 * Type weights are merged (partial overrides fill from previous layer).
129	 * Scalar values are overridden (last layer wins).
130	 */
131	export function resolvePriorities(
132	  prio: PrioritiesConfig | null,
133	  defaults: PriorityDefaults,
134	  agentId?: string,
135	  project?: string,
136	): ResolvedPriorities {
137	  const resolved: ResolvedPriorities = {
138	    blocked: new Set<string>(),
139	    recallTypeWeight: { ...DEFAULT_TYPE_WEIGHTS, ...defaults.recallTypeWeight },
140	    recallMinScore: defaults.recallMinScore ?? DEFAULT_MIN_SCORE,
141	    maxInjectedChars: defaults.maxInjectedChars ?? DEFAULT_MAX_CHARS,
142	    tier: defaults.tier ?? DEFAULT_TIER,
143	    scopeVisibility: null,
144	    captureScope: null,
145	  };
146	
147	  if (!prio) return resolved;
148	
149	  // Layer 1: Global
150	  if (prio.blocked) {
151	    for (const b of prio.blocked) resolved.blocked.add(b);
152	  }
153	  if (prio.recallTypeWeight) {
154	    resolved.recallTypeWeight = { ...resolved.recallTypeWeight, ...prio.recallTypeWeight };
155	  }
156	  if (prio.recallMinScore !== undefined) {
157	    resolved.recallMinScore = Number(prio.recallMinScore);
158	  }
159	  if (prio.maxInjectedChars !== undefined) {
160	    resolved.maxInjectedChars = Number(prio.maxInjectedChars);
161	  }
162	  if (prio.tier !== undefined) {
163	    resolved.tier = prio.tier;
164	  }
165	
166	  // Layer 2: Agent override
167	  if (agentId) {
168	    const agentCfg = prio.agents?.[agentId];
169	    if (agentCfg) {
170	      if (agentCfg.blocked) {
171	        for (const b of agentCfg.blocked) resolved.blocked.add(b);
172	      }
173	      if (agentCfg.recallTypeWeight) {
174	        resolved.recallTypeWeight = { ...resolved.recallTypeWeight, ...agentCfg.recallTypeWeight };
175	      }
176	      if (agentCfg.recallMinScore !== undefined) {
177	        resolved.recallMinScore = Number(agentCfg.recallMinScore);
178	      }
179	      if (agentCfg.maxInjectedChars !== undefined) {
180	        resolved.maxInjectedChars = Number(agentCfg.maxInjectedChars);
181	      }
182	      if (agentCfg.tier !== undefined) {
183	        resolved.tier = agentCfg.tier;
184	      }
185	      if (agentCfg.scopeVisibility) {
186	        resolved.scopeVisibility = [...agentCfg.scopeVisibility];
187	      }
188	      if (agentCfg.captureScope) {
189	        resolved.captureScope = agentCfg.captureScope;
190	      }
191	    }
192	  }
193	
194	  // Layer 3: Project override (only blocked + recallTypeWeight)
195	  if (project) {
196	    const projCfg = prio.projects?.[project];
197	    if (projCfg) {
198	      if (projCfg.blocked) {
199	        for (const b of projCfg.blocked) resolved.blocked.add(b);
200	      }
201	      if (projCfg.recallTypeWeight) {
202	        resolved.recallTypeWeight = { ...resolved.recallTypeWeight, ...projCfg.recallTypeWeight };
203	      }
204	    }
205	  }
206	
207	  return resolved;
208	}
209	
210	// ============================================================================
211	// Blocking
212	// ============================================================================
213	
214	/**
215	 * Check if an entry ID is blocked (exact or prefix match).
216	 * Prefix match requires the blocked prefix to be at least 8 chars.
217	 */
218	export function isBlocked(entryId: string, blocked: Set<string>): boolean {
219	  if (blocked.has(entryId)) return true;
220	  for (const b of blocked) {
221	    if (b.length >= 8 && entryId.startsWith(b)) return true;
222	  }
223	  return false;
224	}
225	
226	/**
227	 * Filter out blocked entries from a list.
228	 * Each entry must have an `id` property.
229	 */
230	export function filterBlocked<T extends { id: string }>(entries: T[], blocked: Set<string>): T[] {
231	  if (blocked.size === 0) return entries;
232	  return entries.filter((e) => !isBlocked(e.id, blocked));
233	}
